/* 本文件由 build_lectures.py 生成，勿手改。源：Obsidian/MyNotes/学习/风水教材/0N-精讲-*.md */
const LECTURES=[{"c":"A","name":"总论与门派","intro":"五本教材的跨教材整合稿。**只用教材原文，不补外部风水知识**；各本讲法不一致处两边都列、标出处，不替作者取舍。 出处标记：`初级`＝杨公风水初级合集｜`中级`＝中级合集｜`家居`＝家居风水高级课程｜`高级`＝高级合集｜`第一课`＝风水第一课1-27。 页码可回查同目录的五本 md。","items":[{"n":"A1","t":"风水是什么","blocks":[{"t":"lead","v":"风水是环境对人的影响，落到操作上就是四个字——<b>藏风、得水</b>。"},{"t":"p","v":"教材给了两个层次的定义，一个白话、一个术语："},{"t":"q","v":["风水：就是我们居住的环境，感受到的空气，流动的水源对我们的影响。"],"src":"初级 p6"},{"t":"q","v":["风水：即藏风得水。"],"src":"家居 p13 图注"},{"t":"q","v":["在我师父眼里：风水就是人们在择地而居时，进行环境选址和布局的学问。"],"src":"第一课 第1课"},{"t":"p","v":"三本说的是同一件事，只是话往哪边说：初级从\"空气和水\"讲影响，家居直接给术语，第一课强调它是<b>选址与布局</b>的学问——今天买房仍然是先选位置再布置内部，只不过在风水师眼里选址叫寻龙点穴。"},{"t":"p","v":"<b>词源上</b>，风水又称堪舆："},{"t":"q","v":["堪是堪天，察看天象。舆是察地。观察环境对人的影响。"],"src":"初级 p9"},{"t":"p","v":"<b>这一条最要紧的是它划的边界</b>：风水讲的是人与环境如何相处，不是预测学。教材把易经分成两支来说明这件事——"},{"t":"q","v":["易经分为两大派：1、义理；2、象数：八字、奇门、梅花、六壬、六爻、太乙等。象数的这些学问其实都是预测的学问，是预测人生的运势或某一事件。而风水讲的是环境对人的影响的学问。"],"src":"初级 p9"},{"t":"src","v":"初级 p6,9｜家居 p13｜第一课 第1课"}],"nq":5,"c":437},{"n":"A2","t":"藏风：要环抱，但要的是动态平衡","blocks":[{"t":"lead","v":"藏风不是把风关住，是让风<b>能进来、能停一停、还能出去</b>。"},{"t":"q","v":["藏风：左右两边一定要有山环抱，龙虎环抱，前面要有案山，这样才能藏风。"],"src":"初级 p6"},{"t":"p","v":"初级紧接着就把这句话往回收了一步，这是全条的关键："},{"t":"q","v":["前面和左右都有高楼环抱，又太过了。有山环抱是一个辩证的概念，山不能太高，太高外面的空气进来不了，里面的空气出去不了。叫<b>逼压</b>或<b>闭气</b>。太低，风又是自来自去，随时处于一个泄气的状态，叫<b>漏风</b>。"],"src":"初级 p6"},{"t":"q","v":["好的风水有山环抱，是一个高低适中的概念。好的风能够进来，是一个可以停聚但是又是流动的状态。相当于是半停聚半流动的状态。进来了又可以出去。<b>不是说风进来就不动就是藏风。如地下室藏风，但不能居住。</b>"],"src":"初级 p6"},{"t":"p","v":"\"地下室藏风但不能住\"这个例子，是判断学没学懂的分水岭：把藏风理解成密闭，方向就反了。教材给这个状态起的名字是<b>动态平衡</b>。"},{"t":"p","v":"初级还引了南怀瑾的说法并给了自己的解释："},{"t":"q","v":["南怀瑾说：风水就是避风避水。其实也没有错。避风就是好的风要藏，不好的风要避。"],"src":"初级 p6"},{"t":"p","v":"<b>家居这本把同一条原理搬进了城市</b>："},{"t":"q","v":["城市的楼房怎么看藏风？四周有建筑环抱，四周高中间低，形如锅底。是非常典型的藏风。"],"src":"家居 p15"},{"t":"q","v":["藏风的要求也是四周的山太高是不行的。太低是空旷不藏风，太高是逼压。"],"src":"家居 p20"},{"t":"note","k":"key","v":"<b>跨教材差异</b>：初级讲的是山地的原理（山环抱、案山、高低适中），家居讲的是同一原理在城市的<b>表现形式</b>（楼宇环抱、锅底形）和<b>室内的表现</b>（见 A3 穿堂煞）。两本不冲突，是一条原理的三个场景。"},{"t":"src","v":"初级 p6｜家居 p15,20"}],"nq":6,"c":655},{"n":"A3","t":"不藏风的几种形态","blocks":[{"t":"lead","v":"把\"不藏风\"认全了，藏风才算真懂——教材列的是<b>凹风、天白、天斩煞、窝煞、穿堂煞</b>。"},{"t":"p","v":"这几个名目分散在两本里，合起来才是完整的一组。按<b>阳风（高处来）／阴风（低处来）</b>分："},{"t":"p","v":"<b>阳风一类</b>"},{"t":"q","v":["如四周有山环抱的地方，某个地方有个缺，能看到天空天白，中间凹下去了，叫<b>凹风</b>。因为山有起有伏，两山之间比较低的也叫过峡。<b>口浅危害小，口深危害大。</b>遇到凹风要避掉。"],"src":"家居 p15"},{"t":"q","v":["<b>不深的叫天白，深的叫凹风。</b>高处天堑煞叫阳风天白。天白和凹风都是阳风。"],"src":"家居 p17 图注"},{"t":"q","v":["城市里不藏风，两栋楼房之间小的缝隙叫<b>天斩煞</b>。天斩煞的风吹过来是很刚烈的。<b>古人没有天斩煞的说法，只叫凹风。</b>"],"src":"家居 p16"},{"t":"p","v":"最后半句值得记：天斩煞是今人给城市形态起的新名字，在老体系里它就是凹风。"},{"t":"p","v":"<b>阴风一类</b>"},{"t":"q","v":["温氏宗祠，房子旁边有很深的沟或者房子正后面有沟，叫<b>阴风窝煞</b>。低处的叫阴风窝煞。"],"src":"家居 p17 图注"},{"t":"q","v":["窝煞在正后方也算，在两边也算。"],"src":"家居 p18"},{"t":"p","v":"<b>室内一类</b>"},{"t":"q","v":["在室内的形峦风水中也有不藏风的布局，如客厅餐厅阳台相对，窗户风对流，为<b>穿堂煞</b>。是室内不藏风的表现。"],"src":"家居 p20"},{"t":"q","v":["在室内两个窗户直对就是不藏风。有什么影响？室内不藏风，如果外山外水也不好，首先是不聚财，其次影响健康。怎么避免呢？哪一边窗户不常开，需要通风时才开，不通风不开即可。"],"src":"家居 p20"},{"t":"note","k":"warn","v":"<b>两条不能漏的但书</b>，否则会把这些名目用成教条："},{"t":"q","v":["只有有玉带水，玉带水的两边一定有窝煞。<b>并不是所有的玉带水都好。</b>"],"src":"家居 p19"},{"t":"q","v":["当然也不是所有的窝煞都不好。如廖家的七星祠，七星祠背后也是窝煞，但它的窝煞制化的很好。……城市里的窝煞比较宽大，七星祠的窝煞也是非常宽大，不会影响太大。"],"src":"家居 p19"},{"t":"p","v":"<b>化解</b>教材只给了一个具体做法："},{"t":"q","v":["温氏宗祠，两边有沟就是窝煞。化解方法：把两边的房子拆开，厢房挡住了两边的窝煞，窝煞就减轻了。这样人丁就旺起来了。"],"src":"家居 p18"},{"t":"p","v":"避凹风的做法在初级："},{"t":"q","v":["我们站在房屋或一个穴场或一个地，两山之间有凹风或天白，避开有很多方法，有<b>修砂手，开水池</b>，就是避风。"],"src":"初级 p6"},{"t":"note","k":"ref","v":"形煞的完整内容见 <b>D 峦头·砂</b>，这里只收\"作为藏风反面\"的那一组。"},{"t":"src","v":"初级 p6｜家居 p15,16,17,18,19,20"}],"nq":11,"c":916},{"n":"A4","t":"得水：关键是\"停聚\"","blocks":[{"t":"lead","v":"有水不算得水，<b>水要停得住</b>才算。"},{"t":"q","v":["水：有水停聚，叫得水。风水得水为上。水停在房屋的前面，向上观水。"],"src":"初级 p6"},{"t":"q","v":["有水的地方，龙水交汇，龙气在这里停聚才会真正的有地。所以说，<b>有水是最关键的</b>。"],"src":"初级 p6"},{"t":"p","v":"教材把\"好风水\"归到两条，第二条专讲怎么让水停下来："},{"t":"q","v":["好的风水：1、有山环抱，2、有水停聚。有水停聚的方法：左水倒右，右水倒左，正前方有逆水而来，之玄水上堂，<b>不管什么办法，总之是有水停在这里的</b>。"],"src":"初级 p7"},{"t":"p","v":"《葬经》的原话，初级和第一课都引了，可见分量："},{"t":"q","v":["郭璞《葬经》：<b>1、藏风得水，得水为上，藏风次之。</b>2、四灵兽概念；3、土质的好坏：细而不坚，润而不泽，砌如肪脂，形如五色。"],"src":"初级 p9"},{"t":"q","v":["首次提到风水二字的风水书是《葬经》，书中讲到：风水之法，得水为上，藏风次之。"],"src":"第一课 第1课"},{"t":"note","k":"warn","v":"<b>注意排序</b>：得水为上、藏风次之——两者都要，但水优先。"},{"t":"note","k":"ref","v":"水的完整内容（水形吉凶、水口、明堂）见 <b>E 峦头·水</b>。"},{"t":"src","v":"初级 p6,7,9｜第一课 第1课"}],"nq":5,"c":414},{"n":"A5","t":"风水影响什么：丁、财、贵、寿","blocks":[{"t":"lead","v":"教材把风水的作用归为四项并<b>明确排了序</b>——丁、财、贵、寿。"},{"t":"q","v":["好风水对人的影响：丁、财、贵、寿","<b>丁为第一位</b>，好的风水要有人丁的延续，没有人丁什么也没有。","<b>财为第二位</b>，有了丁，要有钱才能生存。山管人丁水管财。水对财的影响就很大。","<b>贵为第三位</b>，就是要有知识有文化。","<b>寿为第四位</b>，有了贵之后，身体也要好，要能长寿。"],"src":"初级 p7"},{"t":"p","v":"家居这本用了同样的四个字，作为课程的\"价值\"："},{"t":"q","v":["价值：丁、财、贵、寿"],"src":"家居 p35"},{"t":"note","k":"warn","v":"<b>「山管人丁水管财」不是死规矩</b>，初级当场就补了一句："},{"t":"q","v":["也不是绝对的，很多时候，<b>山也主财，水也主丁</b>。有时候犯到不好的理，比如流破先后天，这个地方没有做好，真的就绝丁了。<b>任何时候看风水要有一个整体观的概念。</b>"],"src":"初级 p7"},{"t":"src","v":"初级 p7｜家居 p35"}],"nq":3,"c":347},{"n":"A6","t":"风水不是什么：四条辟谣","blocks":[{"t":"lead","v":"教材开篇就先划掉四件事。"},{"t":"q","v":["二、风水的误区：","1、风水不是决定我们的一切。风水就是外在环境对人影响的一门学问。选择一个好的风水就是选择一个好的环境。","2、风水不是迷信。","3、风水不是摆放吉祥物的学问。","4、风水不是算命。"],"src":"初级 p7"},{"t":"p","v":"第 3 条在《风水第一课》里展开成了一整课，论据是查典籍："},{"t":"q","v":["我可以负责任的告诉大家：在千年的风水文化传承中，<b>没有任何一本风水古籍书讲到摆放吉祥物就是风水</b>。"],"src":"第一课 第1课"},{"t":"q","v":["再比如，当今民间最为流行的一本风水著作——《地理五诀》，其中就有讲到：风水，古时称之为地理，地理者，即山脉、河川之走势与形势也，故论龙必论水。"],"src":"第一课 第1课"},{"t":"q","v":["我师父、师爷走了一辈子地理，一生帮人看风水，也从来没有说摆放吉祥物是风水。"],"src":"第一课 第1课"},{"t":"note","k":"key","v":"<b>这四条不是态度表白，是操作边界</b>：把风水当成\"摆件学\"，就不会去看外面的山水，而教材的第四条原则（A7）恰恰说外山外水的影响远大于室内摆设。"},{"t":"p","v":"<b>另有一组针对三合派的具体辟谣</b>，性质不同（是派内用法之辩，不是常识辟谣），见 A10。"},{"t":"src","v":"初级 p7｜第一课 第1课"}],"nq":4,"c":433},{"n":"A7","t":"看风水的四条原则","blocks":[{"t":"lead","v":"整体观、阴阳协调居中、相山如相人、四两房屋千斤门楼。"},{"t":"h","v":"一、整体观"},{"t":"q","v":["不能只看堂局、环抱、水、还要看来龙。<b>富贵龙身出。</b>扬其所长，避其所短。"],"src":"初级 p8"},{"t":"p","v":"家居里有个直接的反例，说明只看明堂不看龙会错到哪："},{"t":"q","v":["也不是所有的峰峦顿起旺人丁，<b>还要加上来龙有力才能旺人丁</b>。如果来龙无力，仅仅是峰峦顿起，属<b>虚花假穴</b>，旺不了丁，昙花一现，能发达一代两代就没有了。<b>龙排第一位，其次才是砂。</b>"],"src":"家居 p38"},{"t":"h","v":"二、阴阳协调居中"},{"t":"q","v":["要像太师椅一样坐在中间。面前的堂局一定是左右协调的。看到山峰很秀丽，非要对着山峰。可能一对着山峰，堂局就歪了。<b>如果是为了满足仙命的生克去改向，导致堂局不正，导致失去了阴阳协调居中的原则。</b>"],"src":"初级 p8"},{"t":"note","k":"key","v":"这条是<b>取舍规则</b>：秀峰、仙命生克都要让位于堂局端正。"},{"t":"h","v":"三、相山如同相人"},{"t":"q","v":["山上的草木相当于人的毛发，山上的土壤相当于人的皮肤，山中间的石头相当于人的骨骼。山中的泉水相当于人的血液。所以看山如同看人。"],"src":"初级 p8"},{"t":"q","v":["北方的太行山高大又直，生的人比南方的高大。南方江浙一带的山比较小巧，生的人个子相对比较小巧一点。四川绵阳山如峨眉，出美女不为怪。<b>什么样的山出什么样的人。</b>"],"src":"初级 p8,p99,p375,p413"},{"t":"p","v":"教材给了一个具体验证："},{"t":"q","v":["福建德化一个县里的一个村，大多数家庭都是双胞胎。生双胞胎的家庭都能看到癸丑方的山峰，一共有12户人家，都能看到癸丑方的山峰。"],"src":"初级 p8"},{"t":"h","v":"四、\"四两的房屋，千斤的门楼\""},{"t":"q","v":["<b>外山外水一定大于室内布局对人的影响。</b>通过门楼看到的外山外水或城市高楼的阳台看到别的楼、路对人的影响，远远大于房间里面床怎么安，厨房书房怎么布，西南缺不缺角，厨房在西北好不好。"],"src":"初级 p8"},{"t":"note","k":"key","v":"这条直接决定<b>看房子的顺序</b>：先外后内。它也是 A6 第三条误区的正面表述。"},{"t":"p","v":"初级在这条下面接了一个两面案例，讲同一个尖峰为何一家发文秀、一家发火灾："},{"t":"q","v":["能不能出读书人……看文昌，看有没有贪狼尖峰。不尖不贵，<b>尖奇砂曜多生贵</b>，一定是尖的山峰发文秀。"],"src":"初级 p8"},{"t":"q","v":["<b>当然并不是所有尖的山峰都能起到好作用。尖的山峰也是廉贞火。</b>师爷1987年在福建泉州给一家人做风水，那村里有一个风水先生自己家修了一个房子，乾山巽向巽峰，山峰很秀丽，就是贪狼木。他用28宿消峰，认为\"乾坤艮巽为木，木木比和为旺峰，我孙子两岁，将来要出大学生。\"师爷说乾山巽向巽峰，出不了大学生，2015年要发火灾。果然到了2015年一把无明之火把房子烧掉了。……发火灾原因就是<b>翻卦掌翻到廉贞峰</b>。"],"src":"初级 p8"},{"t":"note","k":"ref","v":"同一个案例在《第一课》第 4、5 课以通俗版讲了一遍（贪狼木主文贵、罗盘推算后可能反成火灾），可对照读。峰的吉凶推算见 <b>B 峦头·龙</b>（五星九星）与 <b>H 理气·水法砂法</b>（翻卦、消峰）。"},{"t":"src","v":"初级 p8,99,375,413｜家居 p38"}],"nq":9,"c":1146},{"n":"A8","t":"峦头与理气：不是两派，是一件事的两半","blocks":[{"t":"lead","v":"<b>理气无峦头不准，峦头无理气不灵。</b>"},{"t":"q","v":["用罗盘测量的风水叫<b>理气</b>，用眼睛看的风水叫<b>峦头</b>。<b>不管哪个门派峦头都是一样的，龙穴砂水向。</b>"],"src":"初级 p10"},{"t":"note","k":"key","v":"<b>这句话五本教材里有四本都讲了</b>，是全套里复述最密的一条纲领："},{"t":"q","v":["理气无峦头不准，峦头无理气不灵。如同孤阴不长，孤阳不生。","只用罗盘看风水叫纸上谈兵，不懂峦头连基本的环境都不会看。只懂峦头不懂罗盘怎么测量，只能说只懂一点皮毛还没有入门，这在风水爱好者中比较普遍。<b>只有峦头与理气结合才知道好与差在哪里，发生哪些事情，何时发生。</b>","如前山逼压，房屋要抬高50公分就不逼压了。"],"src":"初级 p11"},{"t":"q","v":["峦头用肉眼看，理气用罗盘来测量。峦头和理气是风水的两个组成部分。理气无峦头不准，峦头无理气不灵。"],"src":"中级 p173"},{"t":"q","v":["理气无峦头不准，峦头无理气不灵。<b>如果理气不建立在峦头上，你飞星飞的再好，再怎么旺山旺向，没用。</b>"],"src":"家居 p79"},{"t":"p","v":"最后这句（家居 p75）是四处里最见锋芒的——它直接点名了玄空飞星脱离峦头的空转。"},{"t":"p","v":"<b>《第一课》第 6 课专门考证了\"峦头派／理气派\"这个分法站不站得住</b>，给了两条理由："},{"t":"q","v":["第一点：因为我们风水行业祖师爷杨筠松杨公不仅写了很多峦头著作，如《撼龙经》《疑龙经》，更写了《天玉经》《青囊奥语》等等理气方面的著作。"],"src":"第一课 第6课"},{"t":"q","v":["第二点：……在北宋时期，王伋被贬江西赣州，因仕途不顺，忿fèn 而改学地理，也就是说<b>他的风水是在江西赣州学的</b>，而赣州是杨公风水的发源地，那么所学的极有可能就是杨公风水。"],"src":"第一课 第6课"},{"t":"p","v":"并拿王伋自己留下的《地钳记》作证——六句里前四句全是峦头，最后两句才是理气："},{"t":"q","v":["\"魏溪坑口望薰冈，黄蛇捕鼠是真龙，但看七寸安正穴，四柱擎天将相峰。若问子孙官职位，寅申巳亥产英雄。\"","……这四句话没有一句在说理气，都是在讲用眼睛如何看风水，在讲峦头。他讲完峦头后，最后两句讲理气了……这里讲到寅申巳亥，那一定是用罗盘测量坐山朝向和山峰方位才讲的。"],"src":"第一课 第6课"},{"t":"q","v":["所以，把风水分为峦头派和理气派，<b>只是著书的作者一厢情愿罢了</b>。"],"src":"第一课 第6课"},{"t":"note","k":"ref","v":"明朝王祎《青岩丛录》把杨筠松、曾文辿一路称\"江西之法\"（今之峦头派），把王伋一路称\"宗庙之法\"（今之理气派）——<b>这个分法本身古已有之，教材反对的是它成立</b>。〔第一课 第6课〕"},{"t":"src","v":"初级 p10,11｜中级 p173｜家居 p79｜第一课 第6课"}],"nq":8,"c":959},{"n":"A9","t":"派别是怎么产生的","blocks":[{"t":"lead","v":"派别全是<b>理气</b>上分出来的，峦头没有派别；而分化的根源是传承残缺。"},{"t":"q","v":["如今的风水派别的产生是<b>从理气上产生的</b>。……罗盘上每一圈都是不同的理论。就诞生了八宅、三元、三合、玄空、辅星水法等派别。"],"src":"初级 p10"},{"t":"q","v":["不管是哪一个派别，峦头风水都是一样的，没有差别，内容上基本相同，都是讲究背山面水，依山傍水，群山环抱为吉。<b>只有到了用罗盘的时候，测量和理气上的推算方法不一样，产生了不同的派别。</b>"],"src":"第一课 第7课"},{"t":"p","v":"<b>为什么明清才分化</b>，《第一课》给的是历史线索："},{"t":"q","v":["在古代，风水文化很少在民间流传，只有士大夫阶层和朝廷所掌握。到了唐朝末期，在朝廷掌握风水术的人就是……杨筠松，杨公当时的官职是光禄大夫，专门掌管地理灵台事。到了唐朝末年黄巢起义时，天下大乱，杨公带着他的风水学术，来到了江西民间，自此，开始了风水在民间的传播。"],"src":"第一课 第7课"},{"t":"q","v":["因为风水之术历来传承隐秘，只有弟子经历了严格的品德考验，才肯倾囊相授。所以大多数前来学习者，也只学得风水皮毛。加上前来求学后的弟子，回到家乡，再收徒也不肯轻易相授，<b>这导致了风水在曾廖两家之外的传承残缺不全，时间一长，就产生了诸多派别</b>。"],"src":"第一课 第7课"},{"t":"note","k":"key","v":"初级说得更直白，连同门之内都有差别："},{"t":"q","v":["此学问不只是曾家与廖家有区别，内部也有区别，就是两兄弟之间也有区别。<b>有区别的原因是因为很守密。</b>"],"src":"初级 p10"},{"t":"src","v":"初级 p10｜第一课 第7课"}],"nq":5,"c":567},{"n":"A10","t":"各派口诀在杨公体系里的位置","blocks":[{"t":"lead","v":"这些派别的内容多半是真的，<b>错在用法</b>——把一个点当成了全体。"},{"t":"q","v":["其实每个派别在三僚里面都能找到他的出处，都是风水当中的某个口诀某个点，<b>不能只拿某种派别的风水去布局风水、去开门楼、看房间里怎么摆放</b>。"],"src":"初级 p10"},{"t":"q","v":["不管是三合派还是三元派等很多口诀其实就是三僚杨公风水中里面的，正因为这样大多数门派都称杨公为祖师爷，都是杨公传出去的，<b>但是就是因为用法搞错了，口诀就成了门派了</b>。"],"src":"家居 p12"},{"t":"p","v":"三个具体的定位："},{"t":"p","v":"<b>玄空</b>——只用来推应期，不用来布局："},{"t":"q","v":["玄空风水的用法是这个地做下去后，何时起作用，何时发丁，何时出读书人，哪年出，是用玄空来推算的。<b>不是用玄空风水来布局。更不会用八宅来安床。</b>"],"src":"初级 p10"},{"t":"q","v":["玄空风水是出自杨公风水一脉。其内容是真的，只是在我们杨公风水体系里，用法完全不一样，<b>我们只在做好风水后，推算这个风水什么时间起运</b>，也就是什么时间开始起作用，才会用到玄空风水，绝不会用玄空风水来布局风水。"],"src":"第一课 第7课"},{"t":"p","v":"<b>三合</b>——用于房份推算："},{"t":"q","v":["所谓三合就是申子辰合水局，寅午戌合火局，巳酉丑合金局，亥卯未合木局。这一派的流行要感谢在清朝四川做官的赵九峰，他写了两本广为流传的风水书，一本是《地理五诀》，一本是《阳宅三要》。……然我们纵观其内容，只是杨公风水体系中的一个点，不是杨公风水全部。<b>在我们曾廖两家风水体系中，三合风水常常用于房份推算。</b>"],"src":"第一课 第7课"},{"t":"q","v":["这些口诀过去很守密，在传承的过程中很多只学了一个点，包括学的最多的三合，民间有师承的，<b>90%是三合派</b>，都是讲《地理五诀》。"],"src":"初级 p10"},{"t":"p","v":"<b>针对三合派用法的三条具体辨正</b>〔家居 p114〕："},{"t":"q","v":["1、三合风水派用的是天地人三盘，地盘立向，人盘消砂，天盘收水。<b>注：杨公风水只用地盘。</b>","2、民间讲消水只讲天干来水去水，地支水不可来不可去，这个说法也是错误的。<b>注：天干地支水都可来可去。</b>","3、十二长生里要吉水可来，凶水只能去。<b>注：实际上来水去水都可吉可凶，不影响吉凶。</b>"],"src":""},{"t":"note","k":"warn","v":"第 1 条（只用地盘）是<b>与三合派最根本的分歧</b>，会一路影响到罗盘怎么用、峰怎么消、水怎么收。📎 见 <b>J 罗盘与分金</b>。"},{"t":"src","v":"初级 p10｜家居 p12,114｜第一课 第7课"}],"nq":7,"c":932},{"n":"A11","t":"源流：从《葬经》到三僚曾廖两家","blocks":[{"t":"lead","v":"郭璞《葬经》立纲 → 杨筠松传入江西民间 → 曾廖两家家传至今。"},{"t":"p","v":"<b>《葬经》给了三样东西</b>："},{"t":"q","v":["郭璞《葬经》：1、藏风得水，得水为上，藏风次之；2、四灵兽概念；3、土质的好坏：细而不坚，润而不泽，砌如肪脂，形如五色。"],"src":"初级 p9"},{"t":"p","v":"<b>杨公与弟子</b>："},{"t":"q","v":["杨公先后收有廖三传、曾文辿、刘江东等弟子。其中曾廖两家将杨公的风水学术作为家传，在家族中代代相传，一直传到今天。"],"src":"第一课 第7课"},{"t":"p","v":"<b>明朝是高峰</b>："},{"t":"q","v":["杨筠松一脉相传到了明朝，廖均卿为皇家御用风水师，主持朱棣时期迁都北京，参与修建十三陵、故宫等。在嘉靖皇帝时期，廖文正被钦点为<b>风水状元</b>。"],"src":"初级 p9"},{"t":"q","v":["在十三陵中，有近一半的皇陵为江西曾廖两家风水博士所作。……明朝中期，廖家廖文政帮修完十三陵中的永陵、昭陵及改迁湖北的显陵后，回到家乡……在村里专门修有<b>莲泉书院</b>一座，用于风水教学。这个莲泉书院从明朝一直使用到太平天国，被战火所烧，今天还能看到废墟。"],"src":"第一课 第7课"},{"t":"note","k":"warn","v":"<b>书院名两本用字不同，未擅改</b>：第一课作「<b>莲</b>泉书院」〔第一课 第7课〕，家居讲察砂时作「<b>廉</b>泉书院……是教学风水的书院」〔家居 p167〕。两处指的应是同一所（都在三僚、都用于风水教学），用字待考。"},{"t":"note","k":"warn","v":"<b>两本的人名与身份有出入，未擅改</b>：初级作「廖文正……被钦点为风水状元……修改了湖北钟祥的显陵」〔初级 p6〕，第一课作「廖文政帮修完十三陵中的永陵、昭陵及改迁湖北的显陵」〔第一课 第7课〕。<b>「廖文正」与「廖文政」是否同一人，两本没有交代</b>，需查证后再定。"},{"t":"p","v":"<b>显陵改动四条</b>（初级 p6，讲的是理论怎么落到实物上，值得整段收）："},{"t":"q","v":["1、把原来的堡城不用，迁移到后面的堡城，因前面堡城地势太低，棺木进水，把棺木移到后面的城堡里。前面的坟依然保留，只是空坟。<b>所以叫8字坟。</b>","2、把前面坟墓里挖了一条水道连接到前面的水池里，水池里的水有多深坟墓里的水就有多深，在同一个平面。这么做的目的是保证后面堡城不进水。","3、后面堡城上面立了碑，一般百姓的碑在坟的前面，而皇陵专门修了一栋楼叫明楼，明楼上立的碑的向也改了。","4、过去明堂是一个很长的明堂，左右砂手也有环抱，但水是当堂直泄，后面高前面低，中间的路改成\"之玄\"路。"],"src":""},{"t":"p","v":"<b>曾廖两家的异同</b>："},{"t":"q","v":["廖家与曾家的基本理论和原则是相同的，只是在运用时两家的侧重点不同。"],"src":"初级 p10"},{"t":"q","v":["曾从正也参与了改动，只是以廖文正为主。都说曾从正没有后代，其实不对，现在在三僚背后还有四五十人，只是曾从正的这些后代没有把曾从正的学术延续下来，传到了别脉中。<b>曾家都不会风水了。</b>……不管怎么说，曾家的学问还是得到了比较好的传承。"],"src":"初级 p10"},{"t":"note","k":"ref","v":"另有宋朝两人常被提及：<b>王伋</b>（被后人误认为理气派祖师，实际在赣州学的）、<b>赖布衣</b>（在罗盘上增加了人盘内容）。〔第一课 第7课〕⚠️ 注意与 A10 第 1 条对读：杨公风水只用地盘，人盘是赖布衣加的。"},{"t":"src","v":"初级 p6,9,10｜家居 p167｜第一课 第7课"}],"nq":7,"c":1240},{"n":"A12","t":"阳宅与阴宅：一套理论，两个场景","blocks":[{"t":"lead","v":"<b>没有专为阳宅或阴宅另造一套</b>，口诀是同一批，用的场景不同。"},{"t":"q","v":["杨公风水中没有说专门针对阳宅或者阴宅研发一套口诀，风水文化的理论就是一个，只是我们用在不同的场景，<b>用在阳宅上叫家居风水，如果用在阴宅上叫阴宅风水</b>。很多口诀既是阳宅在用，也是阴宅在用。"],"src":"家居 p11"},{"t":"q","v":["当然有些口诀是专门针对阳宅的，如<b>文昌位口诀</b>，阴宅有推算贪狼星的方位，阳宅也可以用推算贪狼星的方位。"],"src":"家居 p11"},{"t":"p","v":"初级在讲立向原则时，同一个意思出现了两次："},{"t":"q","v":["阴阳宅一样，只是做法不同。"],"src":"初级 p776,p901"},{"t":"src","v":"初级 p776,901｜家居 p11"}],"nq":3,"c":241},{"n":"A13","t":"学峦头的三步","blocks":[{"t":"lead","v":"先学理论（龙穴砂水向）→ 现场实践 → 敢于断验。"},{"t":"q","v":["<b>第一步：先学习峦头风水理论。</b>从理论上讲：峦头风水有五要素，那就是龙穴砂水向。"],"src":"第一课 第14课"},{"t":"p","v":"《第一课》给了五个字各自的一句话定义，是全套峦头最简的入口："},{"t":"q","v":["<b>龙</b>，就是山脉，在风水上，把延绵起伏不断的山脉看成有生命力的龙，好风水就一定要有好龙脉。","<b>穴</b>，就是知道了龙脉的走向，在龙气停聚，龙水交汇的地方就是穴位，就是我们要找的做风水位置，或修建房屋的位置。","<b>砂</b>，是我们点好穴位后，在穴位前后左右四周的山峰建筑，称为砂。我们站在穴位，面对明堂，左边叫青龙砂，右边叫白虎砂，正前方叫朱雀砂，后方叫玄武砂。","<b>水</b>，是指我们站在点好穴位的位置，观察是否水聚明堂，出水口是否关拦有情。","<b>向</b>，是说龙穴砂水都达到条件后，我们在开始做风水或修房屋时，要立什么坐山朝向，这就是立向。<b>立向需要先从峦头风水考虑立什么向，再在理气风水上考虑具体是坐什么字向，几度几分。</b>"],"src":"第一课 第14课"},{"t":"q","v":["<b>第二步</b>：……峦头风水是风水中实践性极强的内容，只有亲自跟老师在现场实践，看老师在现场是如何辨认、如何操作的，然后你再亲自实践……如果学习峦头风水，我们只是看书籍、看视频、看图片，不去现场实践，那终究是<b>纸上谈兵</b>。"],"src":"第一课 第14课"},{"t":"q","v":["<b>第三步：敢于断验</b>，在生活中不断实践总结。……比如，峦头风水中讲：尖奇砂曜多生贵，如果当您看到是尖奇砂曜的地形时，你就可以问主人家，你家是否出有985、211大学生。"],"src":"第一课 第14课"},{"t":"p","v":"中级对\"峦头难在哪\"有一句补充，与第二步对读："},{"t":"q","v":["学峦头只要跟对老师，靠眼力，相对来说是比较简单的。<b>如果是闭门造车，峦头是最难的。学好峦头后，理气才是最难的。</b>"],"src":"中级 p148"},{"t":"note","k":"ref","v":"五要素各自的展开：<b>B 龙</b>｜<b>C 穴</b>｜<b>D 砂</b>｜<b>E 水</b>｜<b>F 向</b>。"},{"t":"src","v":"中级 p148｜第一课 第14课"}],"nq":5,"c":800},{"n":"","t":"本类未收入精讲的条目","blocks":[{"t":"p","v":"A 类共 46 个知识点，上面 13 条覆盖了主干。以下条目暂未展开，多为课程介绍性内容或与他类重叠："},{"t":"ul","v":["<b>课程结构类</b>：风水理气必学基础、家居风水实操与应用、家居风水理气深层次的应用、大局风水布局、室内风水布局（这些是家居高级 p10 的课程大纲，内容分散在 G/H/I/K 各类）","<b>待归位</b>：类象思维、声音／颜色／形态（初级线下课笔记，疑为形家类象的一组，<b>原文过简，暂未找到完整讲解</b>，需读图或另找出处）","<b>与他类重叠</b>：怎么来学风水文化、当今风水文化的误区、风水门派之谈（与 A6/A9/A10 同源，内容已并入）"]}],"nq":0,"c":278}]},{"c":"B","name":"峦头·龙","intro":"跨教材整合稿，体例同 A。**只用教材原文**；各本讲法不一致处两边都列、标出处。 出处：`初级`｜`中级`｜`家居`＝家居风水高级课程｜`高级`｜`第一课`。 天下哪有十全十美的地，**龙为最要紧，只要龙好，其他的我们都可以裁剪**。〔初级 p27，引师父语〕 **富贵龙身出**。〔初级 p8,p335 等多处〕","items":[{"n":"B1","t":"龙是什么：把不动的山看成动的","blocks":[{"t":"lead","v":"龙＝连绵起伏的山脉；学龙的第一步是承认<b>山是运动变化的</b>。"},{"t":"q","v":["风水里面讲龙，把我们看到的连绵起伏不断的山脉比喻成龙。正因为我们把风水当中的山脉比喻成龙，所以我们看山有一句话叫\"<b>你看山是山，我看山不是山</b>\"。"],"src":"初级 p12"},{"t":"q","v":["为什么说我们看山不是山，我们看山这个山我们认为它都是运动变化的。它没有静止，但是没有学风水的同学，会说那个山就在那里不动。"],"src":"初级 p12"},{"t":"p","v":"家居这本讲城市时把\"为什么比喻成龙\"说得更直接："},{"t":"q","v":["因为<b>山是静止的，水是运动的</b>，但是在风水上，我们把这个山看成运动的山，它有高有低，就好像我们的龙一样，它有起伏变化，这个起伏变化就是我们的龙脉。"],"src":"家居 p119"},{"t":"p","v":"《第一课》给了最简的一句定义，以及<b>来龙去脉</b>这个词的出处："},{"t":"q","v":["龙就是指延绵不断的山脉。在普通人眼里，山是静止不动的，但是，在我们风水师眼里，山是运动变化的。<b>我们把山脉运动变化的过程称为来龙去脉。</b>"],"src":"第一课 第15课"},{"t":"p","v":"<b>看龙看什么？</b> 初级给的顺序是三件事，后面 B2/B4/B6 依次展开："},{"t":"q","v":["行龙点穴须掌握三点：1、龙的行走，2、龙的剥换，3、龙的过峡。"],"src":"初级 p26"},{"t":"src","v":"初级 p12,26｜家居 p119｜第一课 第15课"}],"nq":5,"c":482},{"n":"B2","t":"观龙的行止：龙随水走，入山观水口","blocks":[{"t":"lead","v":"山不会告诉你它往哪走，<b>看山脚下的水往哪流</b>。"},{"t":"q","v":["《地理五诀》：<b>龙随水走，入山观水口。</b>"],"src":"初级 p12"},{"t":"q","v":["学风水要重点看到龙的行止，因为山它是不动的，我们是看山脚下的水是怎么走的龙就是怎么走的，叫龙随水走。这是我们看风水的原则。"],"src":"初级 p12"},{"t":"q","v":["水怎么流山脉就怎么走，所以我们进山之前，我们要看这水口在哪里，就知道这个山往哪里走了。"],"src":"初级 p12"},{"t":"p","v":"<b>这是个现场动作</b>，教材连怎么做都写了："},{"t":"q","v":["所以我们坐车去看风水，还没有到目的地，还没有进村的时候，一般都会头往窗外望一下，<b>看这个路边的河流到底是往哪边流的。这个一定要看清楚。</b>"],"src":"初级 p12"},{"t":"note","k":"warn","v":"<b>难点在平原</b>："},{"t":"q","v":["但在高山，我们看这个山脚下的水，它是特别的明显。但是往往<b>高山落平阳之后，这个水我们就要仔细去观察</b>，很多时候我们观察不清楚，我们就可能认不清楚龙的行走。认不清龙的行走，你就没办法进行后面的点穴。"],"src":"初级 p13"},{"t":"p","v":"初级给了一个自己踩过的例子，说明看漏了水会把干龙认成支脉："},{"t":"q","v":["去四川西昌看了一个地，明明那个水是往身后流的，但是感觉是没有一个山坳，是一个小平地，一个小坡过去之后，水又往前流了。<b>这个地方叫龙的过峡，水往两边分。</b>中间一定有个土堆，但是这个土堆很不明显。这个就是一个大干龙的过峡。……所以，如果大家不去观察这个水流，……<b>整个山脉你要去找龙的行走，要寻龙点穴，这龙就寻掉了</b>，……那你可能找的就是支脉，就不是干龙了。"],"src":"初级 p13"},{"t":"note","k":"key","v":"<b>城市怎么用</b>：家居把同一条搬到城市，关键在\"高低即山水\"——"},{"t":"q","v":["山的起伏变化跟水的方向是一样的。……是龙随水走，<b>两山之间必有水</b>，两座山之间那就有水，就是龙脉的行走。"],"src":"家居 p119"},{"t":"q","v":["在山上或者说在大城市，我们能看到的很多实际上是<b>高处为山，低处为水</b>。"],"src":"家居 p125"},{"t":"note","k":"ref","v":"水口本身的看法见 <b>E 峦头·水</b>。"},{"t":"src","v":"初级 p12,13｜家居 p119,125"}],"nq":8,"c":764},{"n":"B3","t":"枪头鼠尾：什么样的龙不能用","blocks":[{"t":"lead","v":"直而无起伏的山脉是<b>死气</b>，长的叫枪头（死蛇），短的叫鼠尾（死鳝）——<b>枪头莫下，鼠尾莫扦</b>。"},{"t":"q","v":["当然也有直直的一条山脉的情况。那种山岗就不叫龙了，就是没有生气，没有活力，如果比较长的叫<b>死蛇一条</b>，太直了，太僵硬了，没有起伏变化，那这条蛇它就没有活力了，这叫死气。同样如果这个山脉它是直直的一条，但是比较短，我们就叫<b>死鳝</b>。"],"src":"初级 p13"},{"t":"q","v":["在很多风水古籍书死蛇死鳝叫<b>枪头鼠尾</b>，很直叫枪头，……一条山脉脱下来，直直的一条，这种叫枪头。还有短的细的叫鼠尾，老鼠的尾巴，这都是属于死气，没有生气的。"],"src":"初级 p14 图注、p15"},{"t":"q","v":["针对这种枪头鼠尾，在我们风水上是<b>枪头莫下</b>，这种地方就不能够去点风水，不能修房子，不能做阴宅。这种地方就是没地了，太直了，太死气了。枪头地像古代打仗的那种红缨枪。<b>鼠尾莫扦</b>，就是不要你做风水的意思。"],"src":"初级 p15"},{"t":"note","k":"key","v":"<b>应事与断法</b>（这段是教材少见的\"话该怎么说\"的示范）："},{"t":"q","v":["这种很直的枪头鼠尾地，一般都是大凶。过一两代，实际上都不用去分析年运，<b>就三五十年它就无后了</b>。但是你不能说三五十年无后啊。说说眼前的事情，我们怎么断这种地？我们就说，你这个地方葬下去，你的后代，都还挺有本事有能力的。如果是别人家的地，你就跟东家说，<b>这个地方出来的人清高</b>。清高就是样样精通，什么都看不惯，小事不想做，大事做不了。"],"src":"初级 p15"},{"t":"src","v":"初级 p13,14,15"}],"nq":4,"c":597},{"n":"B4","t":"龙的剥换：脱老换新","blocks":[{"t":"lead","v":"龙一节一节往前走，越走越\"年轻\"，这个过程叫剥换；<b>剥换也是量龙力的尺子</b>。"},{"t":"q","v":["山脉就相当于我们的人一样，一代接一代，龙也是这样，一节一节的往前走，从<b>祖宗山</b>传递到<b>少祖山</b>，少祖山再把龙力给<b>父母山</b>，父母山再把龙力给<b>穴星山</b>，穴星山这里才开始做风水。"],"src":"初级 p17"},{"t":"q","v":["剥换在行龙的过程中，它的价值就是<b>脱老换新</b>。后面是老态龙钟的老人家，就是老树。慢慢往前走，出现了新的树枝一样，跟我们人一样，我们家的老祖宗都没有劳动力了，到年轻人，越年轻我们的生命力就越强。<b>到父母山穴星山就是能力最强的</b>……才是风水宝地。"],"src":"初级 p17"},{"t":"note","k":"key","v":"<b>由此得出一条找地的方向</b>："},{"t":"q","v":["我们找地<b>不能在后面去找地，一定是在这前面找地</b>。这才叫龙的剥换。"],"src":"初级 p19"},{"t":"p","v":"<b>剥换有两重意思，第二重才是实战用的</b>："},{"t":"q","v":["学峦头时，不仅要知道龙剥换是龙力传承的一个过程……同时我们还要知道<b>剥换是我们观察龙力大小的一个标准</b>。怎么观察？就是我们要通过剥换的一些特性来观察。"],"src":"初级 p19"},{"t":"p","v":"具体怎么观察 → 见 B7 的三点。"},{"t":"src","v":"初级 p17,19"}],"nq":4,"c":472},{"n":"B5","t":"三大干龙：植被就是龙力的刻度","blocks":[{"t":"lead","v":"中国龙脉自昆仑山发脉分三支，<b>一路的植被由荒到茂，正对应祖宗山→少祖山→父母山</b>。"},{"t":"q","v":["我们整个中国的龙脉，三大干龙是从<b>昆仑山脉</b>开始。"],"src":"初级 p18"},{"t":"p","v":"<b>北龙</b>："},{"t":"q","v":["从阿尔泰山，到大阴山，到大青山，一直到太行山，到我们北京的燕山山脉，北京的燕山山脉经过平谷之后，再到了秦皇岛，到了辽宁。到辽宁的火山就又分两支，一直到大兴安岭，到长白山。长白山到朝鲜，再到日本。这就是北龙。"],"src":"初级 p18"},{"t":"q","v":["以北龙为例……祖宗山在昆仑山，在西北，<b>那里的山都寸草不生</b>。一直往前走，走到山西太行山，<b>慢慢有些绿色了</b>，到了北京的燕山山脉<b>植被就很好了</b>。一直到大兴安岭<b>植被更丰富了</b>。龙力是一步步强的。"],"src":"初级 p18"},{"t":"p","v":"<b>中龙</b>："},{"t":"q","v":["昆仑山脉下来到了秦岭，到了大巴山，大巴山脉在中龙，它又分成了三支，其中南边一支就到成都了，经过莱山、峨眉山、乐山，就止于岷江。这是最短的中龙。……中间的中支就是经过了三门峡这边的伏牛山、熊耳山到嵩山，到泰山，一直到山东的沂山，最后止于山东的海边。中间的这一支，它就是经过大巴山脉，最后汇于大别山。"],"src":"初级 p18"},{"t":"p","v":"<b>南龙</b>："},{"t":"q","v":["经过了唐古拉山到横断山脉，横断山脉到了云南之后，分为两支，一支就是到玉龙雪山，玉龙雪山经过四川大凉山，到了湖北的武陵山、雪峰山，最后到了武夷山脉，这是南龙南边的一支。南龙北边的一支，经过了横断山脉之后就到了贵州，通过贵州的乌蒙山，然后到了广西的九瑶山，然后到广东的佛山、中山、罗浮山，最后汇成九连山。最后分成了大余岭小余岭。"],"src":"初级 p18"},{"t":"note","k":"warn","v":"《第一课》第 16 课也讲三大干龙，与初级同源但更简，<b>并给出了\"为什么发源在西北\"的理由</b>："},{"t":"q","v":["要知道龙脉的发源地，我们还得用<b>龙随水走</b>的原理来寻找。也就是说，水的发源地在哪里，龙脉的发源地就在哪里。我国的大江大河，如长江黄河，发源地都在西北。那我国的龙脉发源地也在西北。"],"src":"第一课 第16课"},{"t":"src","v":"初级 p18｜第一课 第16课"}],"nq":6,"c":798},{"n":"B6","t":"过峡：束气—吐气—起星","blocks":[{"t":"lead","v":"过峡是龙的\"脖子\"，<b>束得越紧，吐得越高，星体越大，龙力越足</b>。"},{"t":"q","v":["一是要观察龙是否有护卫。从这个地形看（如下图），从这个父母山后面一节这里开始剥换，<b>最低的地方叫过峡</b>，在南方叫什么叫垭口。在北方叫山坳，我们专业术语就叫过狭，就是我们人束气的脖子一样。"],"src":"初级 p20"},{"t":"q","v":["因为龙力剥换，在过峡这里开始束气。气一收紧，然后一吐气，就起了星体。我们把龙有<b>束气—吐气—起星</b>这个过程就是整个剥换的过程。……束气，就是这个山往下走的这个过程。吐气就是往上走的，叫吐气。起星，就是起了山叫起星。"],"src":"初级 p20"},{"t":"p","v":"<b>为什么\"越细越好\"</b>，教材用了吹气球作比："},{"t":"q","v":["那个越细就代表束气越紧，吐的气就越高，星体会越大，这龙力就会越足。<b>就跟我们吹气球一样，我们先把气收的越紧的时候，那么我们吐气越多。</b>"],"src":"初级 p22"},{"t":"src","v":"初级 p20,22"}],"nq":3,"c":355},{"n":"B7","t":"看过峡的三点：护卫、迎送、蜂腰鹤膝","blocks":[{"t":"lead","v":"<b>剥换要观察三点</b>——龙是否有护卫、过峡两边是否有迎有送、过峡处是否成鹤膝蜂腰形。"},{"t":"q","v":["剥换要观察三点：1、观察龙是否有护卫。2、过峡两边是否有迎有送。3、过峡处是否成鹤膝蜂腰形。"],"src":"初级 p19,p20"},{"t":"h","v":"一、有护"},{"t":"q","v":["看它是否有护，就是看它束气的这个最低点，这个点的护是怎么护的，其实就是看它这个最低点（过峡）的远处外面<b>看左右两边有没有其他山挡住</b>。"],"src":"初级 p20"},{"t":"q","v":["要是有就代表我们人的脖子一样，冬天吹风的时候，我们有一个衣领挡住，这样我们脖子就不会受风吹。……假如说束气这里没有山挡住，那么它就是跟我们的脖子一样，直接受风吹，在风水上，我们从峦头上说就可以称为<b>病龙</b>。"],"src":"初级 p21"},{"t":"h","v":"二、有迎有送"},{"t":"q","v":["束气往上走的过程当中，两边上会生个支脉出来，叫<b>送</b>。同时，对方山它两边也会生个支脉，叫<b>迎</b>。就是这个过峡左右两边有两个小八字，就相当于我们人的腿一样，或者我们手一样，要有迎有送，这个才叫<b>有情</b>。"],"src":"初级 p22"},{"t":"q","v":["如果没有迎送叫<b>无情</b>，或者说有送无迎，或者说有迎无送，这要决定前面的风水宝地。"],"src":"初级 p22"},{"t":"note","k":"warn","v":"这一点<b>必须现场看</b>，且距离比想象中远——线下课的补充很具体："},{"t":"q","v":["这个必须要现场来看，因为有迎有送它是很细微的。"],"src":"初级 p22"},{"t":"q","v":["〔线下课到现场看时〕两边的迎送不是紧跟过峡处两边，迎山是在穴星山前面过来的一支脉，送的山脉是从父母山后面过来的一支山脉，两支山脉的尽头快要相接没有相接的位置差不多在过峡处的右边，<b>离过峡处大概 1 里—1 公里之间</b>，王老师说这个距离属于正常。迎送山脉之外的远处还有山护卫。"],"src":"初级 p22，线下课补充"},{"t":"h","v":"三、蜂腰鹤膝"},{"t":"q","v":["三是要看过峡的地方是否成鹤膝蜂腰形。在这个过狭的地方，过狭中间最细，就像个蜜蜂的腰一样，这个叫<b>蜂腰</b>。"],"src":"初级 p22"},{"t":"q","v":["<b>鹤膝</b>是束了两次气。龙是往这前面走的，他在束气的时候束到一半又吐一点，又束一次，那么中间就会鼓一个包，这个包就跟那个鸟腿的膝盖一样，鸟腿很细，但是它的膝盖很粗，这叫鹤膝。"],"src":"初级 p23"},{"t":"p","v":"<b>三点齐了才算有情</b>："},{"t":"q","v":["如果过峡达到这三点要求，我们就可以认为这个龙是有情的。"],"src":"初级 p23"},{"t":"q","v":["如果又有护卫又有迎送，是很好的有情。代表这个地很好，将来做了风水，他的后代子孙旺盛。"],"src":"初级 p22"},{"t":"src","v":"初级 p19,20,21,22,23"}],"nq":11,"c":900},{"n":"B8","t":"格龙：站在过峡最低点测","blocks":[{"t":"lead","v":"<b>测来龙要站在过峡最低点往父母山方向格</b>，站穴位对着山顶最高处测是错的。"},{"t":"q","v":["在理气上，我们把这三点观察完之后，要下罗盘来测量。那么在民间一般风水先生测过峡怎么测呢？举个例子，假如说这里他做了个风水，<b>他就是站到这个穴位，直接拿罗盘对准这个山顶最高的地方，说这个叫来龙，是不对的。</b>"],"src":"初级 p23"},{"t":"q","v":["据我观察，除了我们三僚杨公风水千年以来测过峡的方法没有变之外。<b>在民间，我还没有遇到过能够把过峡测准的方法。民间很多测来龙，都是乱来的。</b>"],"src":"初级 p23"},{"t":"p","v":"<b>正确做法与理由</b>："},{"t":"q","v":["真正测过狭是<b>站到这个最低点来测</b>，为什么站这里呢？只有过狭跟我们人的脖子一样，我们才能最容易观察我们的血脉的流动，只有在过峡这里，我们才最容易观察龙脉的走向。"],"src":"初级 p23"},{"t":"q","v":["什么叫格龙？<b>格龙就是测量来龙的意思。</b>为什么说格呢？就是用罗盘十字线对的这个龙，称为格龙。格龙是格来龙从哪个方向来，我们是站到这个最低处用罗盘往这边照（指的是父母山）。看到这个脉是往哪边下来的，束气是往哪里送的，<b>就是格送气的这条脉就是我们的来龙</b>。"],"src":"初级 p23"},{"t":"note","k":"key","v":"<b>格龙为什么重要</b>——它是立向的前置条件："},{"t":"q","v":["测来龙，就是我们要测理气上这个字。他来的哪个字，这个字要跟前面坐山朝向能相配，就是风水上立向的时候非常重要的一个参考数据。<b>如果来龙你格不准，说你会立向，我们认为你这是乱来的。</b>"],"src":"初级 p23"},{"t":"note","k":"warn","v":"教材自己说这条<b>光看讲解学不会</b>："},{"t":"q","v":["真正要格准来龙得初级中级高级线下课的时候去操作，什么样的过峡都去格，才能格准。<b>不是一讲就会的，跟开车一样，得亲自上路开一开。</b>"],"src":"初级 p24"},{"t":"note","k":"ref","v":"罗盘怎么用见 <b>J 罗盘与分金</b>；立向见 <b>F 峦头·向</b>。"},{"t":"src","v":"初级 p23,24"}],"nq":6,"c":718},{"n":"B9","t":"龙的支脉形态","blocks":[{"t":"lead","v":"龙往前走会分支脉，按左右关系分梧桐枝、芍药枝、杨柳枝。"},{"t":"q","v":["当龙脉往前走的过程当中……它不是直直的，它两边又会有支脉。根据支脉的不同，又分很多种，<b>左右对称的叫梧桐枝，左右交叉的叫芍药枝，偏向一边的叫杨柳枝</b>等等，现在只做了解，将来我们在山上找地的时候会带领大家来具体来讲。"],"src":"初级 p25"},{"t":"note","k":"warn","v":"<b>教材明说这里只是\"了解\"</b>，展开在线下课，本套讲义没有更多内容。若要深究需另找出处。"},{"t":"src","v":"初级 p25"}],"nq":1,"c":193},{"n":"B10","t":"地理五星：一流地师观星斗","blocks":[{"t":"lead","v":"<b>地理先须辨五星，木直火尖土星横，金圆水曲多成像，千变万化此中生。</b>"},{"t":"q","v":["只掌握这三点还不行，在观察龙的行止、剥换、过狭的时候，有个最重要的内容，那就是<b>要观察这个山的外形</b>。这个在风水上是非常重要的。风水上有一句话叫\"<b>一流地师观星斗，二流地师关水口，三流地师拿着罗盘到处走</b>\"。"],"src":"初级 p26"},{"t":"note","k":"warn","v":"<b>\"观星斗\"观的是山不是天</b>，《第一课》专门辟了一课讲这件事："},{"t":"q","v":["一流地师就是观的山的外形。……我们观察山的外形，在老远就能知道这个山有没有地，不用去找这个风水宝地，叫一流地师观星斗。<b>不是看天上星星，这个只能说是我们江湖上的一些先生的自创发明。</b>"],"src":"初级 p26"},{"t":"p","v":"<b>五星口诀</b>（初级与第一课字句略有出入，两版都录）："},{"t":"q","v":["地理先须辨五星","木直火尖土星横","金圆水曲多成像","千变万化此中生"],"src":"第一课 第18课"},{"t":"q","v":["先学五星，四句话就是：<b>地理先须辨五行</b>，木直火尖土星横，金圆水曲多成像，千变万化此中生。"],"src":"初级 p27"},{"t":"note","k":"warn","v":"首句初级作「辨五<b>行</b>」、第一课作「辨五<b>星</b>」，<b>一字之差，未擅改</b>，按各自出处保留。"},{"t":"p","v":"<b>释义</b>："},{"t":"q","v":["五行成了五种星体，木星是直的，火星是尖的，土星是横的，金星是圆的，水星是弯弯曲曲的。"],"src":"初级 p27"},{"t":"note","k":"key","v":"<b>最要紧的一条戒律</b>："},{"t":"q","v":["我们在观察这个山形的时候，<b>千万不要犯教条主义，刻舟求剑</b>，就是这个山的外形它是变化的，在风水上有一句话叫\"<b>移步换形</b>\"。横看成岭侧成峰，远近高低各不同。"],"src":"初级 p27"},{"t":"p","v":"家居给了移步换形的实例与处理办法："},{"t":"q","v":["如图片中远处的山，尖峰象火形峰，天气好的时候看，是贪狼木星峰。移步换形。<b>分不清楚时叫木火体即可。</b>"],"src":"家居 p39"},{"t":"src","v":"初级 p26,27｜家居 p39｜第一课 第18课"}],"nq":7,"c":706},{"n":"B11","t":"五星各论","blocks":[{"t":"table","head":["星","形","主"],"rows":[["木","直","贵（尖奇砂曜多生贵）"],["火","尖","见 ⚠️"],["土","横（顶平）","富（圆满出富当无疑）"],["金","圆","富；高大者主贵、主武贵"],["水","曲（波浪）","富贵皆有可能，多见于行龙"]]},{"t":"p","v":"<b>土星</b>"},{"t":"q","v":["土星山峰顶就是平的，两边慢慢下来，底也是平的，就是一个<b>等腰梯形</b>。我们风水上就叫<b>巨门土星</b>。"],"src":"初级 p32"},{"t":"q","v":["土形山峰主富。……刚才讲尖奇砂曜多生贵，这个就是<b>圆满出富当无疑</b>。圆形山峰，就是主富。"],"src":"初级 p34"},{"t":"q","v":["不管城市还是乡下，<b>方形的建筑主富，也主权力</b>。因为它为土，土居中央……政府部门很多建筑都是土形的，主权力。"],"src":"初级 p35"},{"t":"p","v":"教材在这里带出一条喝形的规矩："},{"t":"q","v":["从山形来看，<b>方为狮，圆为虎</b>。这个山形是平的，我们就叫狮子山。"],"src":"初级 p34"},{"t":"p","v":"<b>金星</b>"},{"t":"q","v":["金星山峰主富。木子火尖土星横，土星是平的，金星山峰它的顶是圆的。"],"src":"初级 p36 图注"},{"t":"q","v":["也有金星山峰主贵的时候，<b>特别高大的金星山峰主贵。金星山峰一般是主武贵。</b>"],"src":"初级 p37"},{"t":"q","v":["所以金形山峰主富是没错的，但要记住，高大的金形山峰，因为它高大，很多时候在水口砂，\"<b>外有峰峦插水边，离乡别祖方为贵</b>\"，他就是有发贵的这种特性。"],"src":"初级 p37"},{"t":"note","k":"key","v":"教材用两个将军家的案例说明\"同是金星，高大程度决定贵到哪一级\"，并由此再次强调不可教条："},{"t":"q","v":["我们在看风水的时候千万不要犯教条主义，<b>不要一看到金星山峰，就说是主富的，我们要具体对待</b>。"],"src":"初级 p37"},{"t":"p","v":"<b>水星</b>"},{"t":"q","v":["水星山峰山顶是波浪形的……<b>水星一般是行龙的时候多见</b>，就是龙往前走的时候容易见到水星。一般结穴的时候，水星行龙又开始能结一个星体，<b>一般水星结金星是最多的。水星行龙，金星结穴，金水相生</b>，这种情况是我们最常见的。"],"src":"初级 p38,p39"},{"t":"q","v":["既然是蛇形，我们也叫水星。它是<b>富贵皆有可能主，就是不定的</b>。"],"src":"初级 p39"},{"t":"note","k":"warn","v":"<b>水星有两种情况没有地</b>："},{"t":"q","v":["但并不是所有的这种水星都有地的，假如这个地方它不起这个山包，除山包以外，它就是长长的一个脉，没有用。<b>它就一定要有结穴。</b>〔初级 p39〕","还有这个山脉<b>水星太直，他也没用</b>。它有起伏，所以它是蛇形。"],"src":"初级 p39"},{"t":"p","v":"<b>木星与火星</b>"},{"t":"p","v":"木星（贪狼）详见 B12。火星在初级第2课下开头一句带过，且是与理气连着说的："},{"t":"q","v":["城市里面这种火星山峰，九星就叫<b>廉贞火</b>。火星山峰和贪狼木星，<b>需要把理气结合起来。要避免这种木星山峰、火星山峰，避免它收成了廉贞峰。</b>"],"src":"初级 p32"},{"t":"note","k":"warn","v":"<b>这是全类最需要理气配合的一处</b>：同一座尖峰，峦头上是贪狼木（主文贵），理气推算若落到廉贞，就是火灾。📎 案例见 <b>A7</b> 第四条原则（师爷断 2015 年火灾）与 <b>H 理气·水法砂法</b>（翻卦、消峰）。"},{"t":"src","v":"初级 p32,34,35,36,37,38,39"}],"nq":12,"c":1110},{"n":"B12","t":"九星与贪狼十二形","blocks":[{"t":"lead","v":"五星是基础，<b>九星才是线下课的第一个重点</b>；\"一流地师观星斗\"观的就是九星。"},{"t":"q","v":["九星顺序：<b>贪狼（天枢）、巨门（天璇）、禄存（天玑）、文曲（天权）、廉贞（玉衡）、武曲（开阳）、破军（摇光）、左辅、右弼。</b>"],"src":"初级 p48"},{"t":"p","v":"<b>九星与五星的对应</b>（初级 p48 原文，逐条）："},{"t":"table","head":["九星","五星"],"rows":[["贪狼","木"],["巨门","土"],["禄存","土"],["文曲","水"],["廉贞","火"],["武曲","金"],["破军","大多属金"],["左辅","金"],["右弼","不在五星中"]]},{"t":"q","v":["第九颗星叫右弼星，这类星体<b>一般不在五星中，或说与五星都有些联系，但又不属于五星中的任何一个星体</b>。"],"src":"初级 p48"},{"t":"note","k":"key","v":"<b>学习次第上的一句硬话</b>："},{"t":"q","v":["线下课的重点是论星体，找穴位，是寻龙点穴里最重要的内容。<b>九星是线下课第一个重点。前面讲的五星是一个基础。学了九星后不要再讲五星了。</b>"],"src":"初级 p49"},{"t":"q","v":["风水上的九星，除了用于峦头，<b>还用于理气</b>。易经的其他学科也都用到九星。比如奇门遁甲的天蓬星即贪狼星等。"],"src":"初级 p48"},{"t":"h","v":"贪狼：发贵第一颗星"},{"t":"q","v":["贪狼星是<b>能够发贵的第一颗星</b>。有贪狼星发贵的可能性很大，<b>还要用理气来进一步推算</b>。"],"src":"初级 p50"},{"t":"p","v":"<b>正形五种</b>："},{"t":"q","v":["贪狼木有：<b>平贪、小贪、尖贪、直贪、圆贪。</b>","<b>尖贪</b>：象竹笋一样尖的称为尖贪。","<b>平贪</b>：顶是平的四周是圆的称为平贪，相当于圆锥体把尖削掉了。如果顶上平的再长一点，正前方平一点，则为巨门土。","<b>小贪</b>：象竹笋一样刚冒出一点点，不够明显。","<b>直贪</b>：长长的一条倒地木，象刚砍下来的树木一样。","<b>圆贪</b>：顶是圆形，象金星一样，与金星的区别，顶是圆的但比金星尖，同时也是圆锥体。"],"src":"初级 p50"},{"t":"p","v":"<b>非正形七种，主凶</b>："},{"t":"q","v":["贪狼峰非正形的特点有：<b>欹贪、斜贪、侧贪、石贪、倒贪、破贪、空贪。七者均不是贪狼的正体，主凶。</b>","歪的叫欹贪，倒着的为倒贪，斜向一边的叫斜贪，破碎的叫破贪，中间是空的叫空贪，只有一边有叫侧贪，全是石头的叫石贪。"],"src":"初级 p55"},{"t":"p","v":"（正形五 + 非正形七 = 十二形，即教材所说\"贪狼峰的十二种形状\"。）"},{"t":"p","v":"<b>能不能用来结穴，要分开看</b>："},{"t":"q","v":["不一定每一种贪狼木都是风水宝地，<b>有些贪狼木可以直接结穴</b>，作为穴位来修建房屋。<b>有些贪狼木不能直接修建房屋，只能当作用神山</b>，即青龙白虎朱雀玄武山。用神山能收到贪狼帮我们发富发贵。"],"src":"初级 p51"},{"t":"q","v":["可作为靠山的最常见的是<b>平贪和倒地木</b>……还有可作为穴星山靠山的<b>直贪倒地木</b>，直贪的龙水交汇在树节处。<b>倒地木葬节。</b>现实中，在树节处的房子风水不错。节是长长的一条倒地木有突出来的一块地方，多出来一块平地，即有一个<b>兜唇</b>。"],"src":"初级 p51"},{"t":"p","v":"<b>尖贪火脚</b>："},{"t":"q","v":["<b>尖贪火脚</b>：贪狼木拖了两个脚出来。火脚有一些不祥之意。……这种山形应事：人长的端正，忠良烈士。怎么严刑拷打，也不会告密。"],"src":"初级 p54"},{"t":"h","v":"⭐ 出头：断错与断对的分界"},{"t":"p","v":"教材把这一条称为\"秘不外传的内容\"，值得整段抄下来。案例是：某村有漂亮贪狼峰，出的公务员全县最多，但官职都不大。为什么？"},{"t":"q","v":["诀窍是：贪狼峰 A 确实比远处的山秀丽，<b>不是因为这个贪狼峰小，而是因为它与周边的山比起来它显得太小了，没有出头</b>。它可以应吉，但因为没有出头所以官职小。"],"src":"初级 p52"},{"t":"q","v":["如果贪狼峰后面高大的山B 也这么漂亮。那官职就大了。就象我老家的三台峰，出的是国家副主席，国防部长。"],"src":"初级 p53"},{"t":"q","v":["<b>看风水要掌握\"出头\"的概念，是秘不外传的内容。我们看山还要与周围的山来比较。要不然会断错。</b>"],"src":"初级 p53"},{"t":"p","v":"同一个案例还带出<b>人丁看后龙</b>与<b>开帐</b>："},{"t":"q","v":["为什么人口这么多？原因是后面靠山<b>层层开帐</b>（左右一拉开叫开帐）。来龙特别漂亮。到村里<b>至少是五层靠山</b>。"],"src":"初级 p53"},{"t":"q","v":["《憾龙经》：<b>一重缠山一重关，关门若有千重锁，定有王侯居此间。</b>"],"src":"初级 p53"},{"t":"q","v":["后面层层靠山的两山之间必有水下来，就是关水口的意思。所以后龙特别漂亮。所以人丁兴旺。"],"src":"初级 p53"},{"t":"note","k":"warn","v":"并且教材当场提醒<b>不要因为眼前峰小就断死</b>："},{"t":"q","v":["从后龙来看，不能说一直小贵，后龙也是尖峰，后龙是廉贞火，也会发贵。<b>当龙运地运走到这里时，也会出大贵。</b>地运还没有到后面靠山时一直出小官。……<b>并不能因为前面的贪狼峰没有出头就断一直出小官。</b>"],"src":"初级 p53"},{"t":"q","v":["\"富贵龙身出\"，看地时，<b>后面靠山最重要</b>。风水一定是辩证的，如果来龙不好，不合局，青龙或白虎方好，找到又有什么用呢？来龙不好，前面有一个山头，叫\"<b>虚花假穴</b>\"。"],"src":"初级 p53"},{"t":"src","v":"初级 p48,49,50,51,52,53,54,55"}],"nq":18,"c":1841},{"n":"B13","t":"城市寻龙：干枝之分与结穴两原则","blocks":[{"t":"lead","v":"城市里同样是龙随水走，只是<b>高处为山、低处为水</b>；能不能结穴看两条——<b>开面</b>与<b>龙水交汇</b>。"},{"t":"h","v":"干龙与枝龙"},{"t":"q","v":["龙有大小之分……后面是干龙，干龙开帐之后也是干龙，到房子后面这里就称为<b>枝龙</b>。那么在风水上，这种枝龙能够结穴的往往是结人家，结村庄。"],"src":"家居 p119"},{"t":"q","v":["<b>大干龙结都市城镇，中等龙结县城乡镇。</b>龙有大小之分，了解结穴的过程，<b>我们买房子就知道应该选什么区域</b>。"],"src":"家居 p119"},{"t":"q","v":["有些枝龙，<b>支中有干，干中有枝，枝龙也可以看成干，干和枝是相对的</b>。……我们在总公司有董事长、总经理，分公司也有董事长总经理。"],"src":"家居 p126"},{"t":"p","v":"<b>缠山</b>："},{"t":"q","v":["那么龙在行走的过程当中。就像我们树一样，它就拥有一条条龙脉，这个叫<b>缠山</b>。……有缠山就代表这个龙行走有护，周围有护卫，都一起往前走，就相当于我们一个大人物出场，左右两边的随从都要跟随。"],"src":"家居 p126"},{"t":"h","v":"结穴第一原则：开面"},{"t":"q","v":["这个龙往前走的过程当中，它一定要龙气停聚，<b>一定要开面</b>。"],"src":"家居 p120"},{"t":"q","v":["我们为了修房屋就人为的把这个山给切一小块，这个山后面人为的把它挖平，还挖了几个台阶，在我们风水上，这叫<b>花台</b>。就好比一把我们那个折叠的纸扇打开一样，这叫<b>开面</b>。"],"src":"家居 p122"},{"t":"q","v":["但凡能够修阳宅的地方，那这个山脉一定是要开面，<b>如果没开面，我们人为的都要把它打开</b>……把那这个山切一块下来，把后面做平，就做成我们的椅背，做成靠山，这样子靠的稳。"],"src":"家居 p122"},{"t":"note","k":"warn","v":"<b>不开面的后果</b>："},{"t":"q","v":["如果后龙不开面，后龙这个落脉很急很窄，那这个地就叫<b>坐不稳</b>。"],"src":"家居 p122"},{"t":"q","v":["他没开面，那么这个他左边青龙方就有一条水过来，叫<b>左肩肩煞</b>。右边有一条水过来，叫<b>右肩肩煞</b>。"],"src":"家居 p123"},{"t":"q","v":["开了面之后，要在左边青龙这边要做砂手，右边白虎方有余砂环抱，两边砂手一环抱，那就做成了一个<b>太师椅</b>，一个好的风水格局就是太师椅。"],"src":"家居 p123"},{"t":"h","v":"结穴第二原则：龙气停聚、龙水交汇"},{"t":"q","v":["结穴的第二个原则：龙气停聚，龙水交汇。我们修房子的这个地方，<b>这个龙在这里就不走了</b>。"],"src":"家居 p123"},{"t":"q","v":["这里有一个平地，因为有平地，我们才能修房屋。就像椅子一样，做房子的这个地方一定是平的，不平就坐不稳。这里是平地，<b>前面还要有个余坪</b>。也就是说，平地房子不能够直接修到这里，前面就是悬崖了，前面得有个余坪。<b>余坪前面往下走，就低一个台阶了。高处为山，低处为水，低一个台阶叫龙气停聚。</b>"],"src":"家居 p124"},{"t":"note","k":"warn","v":"<b>余坪不是越宽越好</b>："},{"t":"q","v":["<b>余坪拖的太长</b>，也就是说前面庭院太宽，地势太宽也不行，为什么不行呢？<b>代表龙气没有停聚，代表这个龙气还在往前走。</b>"],"src":"家居 p125"},{"t":"note","k":"ref","v":"穴的完整内容见 <b>C 峦头·穴</b>；砂手、太师椅见 <b>D 峦头·砂</b>；余坪与花台在阳宅上的做法见 <b>K 应用·家居城市</b>。"},{"t":"src","v":"家居 p119,120,122,123,124,125,126"}],"nq":13,"c":1183},{"n":"","t":"本类未收入精讲的条目","blocks":[{"t":"p","v":"B 类共 110 个知识点，上面 13 条覆盖主干。以下暂未展开："},{"t":"ul","v":["<b>九星其余八星的各论</b>（巨门、禄存、文曲、廉贞、武曲、破军、左辅、右弼的形状与应事）——初级第3课上下 p48-95 还有大量内容，本稿只写到贪狼。<b>这是本类最大的缺口</b>，需另起一轮。","<b>廖家九星 vs 杨公九星</b>（穴上九星：太阳、太阴、金水、天财、紫气、天罡、孤曜、燥火、扫荡）——主要在中级 p9-20，且与「五星结穴」连讲，按体例归 <b>C 峦头·穴</b>，那边写。","<b>龙的其余细目</b>：龙分阴阳、龙审气脉、龙的富贵贫贱、龙看住结、龙之生跃、童山/石山/独山/过山/断山（五不葬相关，归 C）、帐幕、横结与闪结——多在初级线下课笔记与中级论地部分，条目零散，待与 C 类一并处理。"]}],"nq":0,"c":345}]},{"c":"C","name":"峦头·穴","intro":"跨教材整合稿，体例同 A、B。**只用教材原文**，引文照录（含原稿的用字与错字，不代改）。 出处：`初级`｜`中级`｜`家居`＝家居风水高级课程｜`高级`｜`第一课`。 **点穴是寻龙的最终目的。**〔初级 p142〕","items":[{"n":"C1","t":"穴：穴场与穴位是两回事","blocks":[{"t":"lead","v":"先圈出<b>穴场</b>（大范围），再定<b>穴位</b>（具体那一点）。"},{"t":"q","v":["穴一是指穴场，二是指穴位。<b>穴：古意是指土室。是人类防风避雨的地方。点穴的地方就是寻找藏风聚气的地方。</b>"],"src":"初级 p141"},{"t":"q","v":["穴位：人体经络有穴位，点穴就是通过选好一个大的范围之后，我们要选一个具体的点。这个点就叫穴位。即修阳宅的点，阴宅挖金井放棺木放金坛这个点，这个点叫穴位。"],"src":"初级 p141"},{"t":"p","v":"<b>为什么借人体作比</b>："},{"t":"q","v":["人体上的穴位是气血最充盈的地方。风水上的点穴也是气血最充盈的地方，<b>是龙气最足的地方</b>，这个叫点穴。"],"src":"初级 p141"},{"t":"note","k":"key","v":"<b>选好位置不等于可以动工</b>，中间还隔着立向："},{"t":"q","v":["做一个房子或阴宅风水，通过寻龙选好位置之后，是不是可以直接建房屋呢？也不行，选好位置好，还要考虑房屋怎么<b>后承龙气</b>，龙气怎么更好地到达房屋，前面能够<b>收堂气</b>，做到藏风得水。这就是风水里面的立向。"],"src":"初级 p141"},{"t":"note","k":"ref","v":"立向见 <b>F 峦头·向</b>。"},{"t":"src","v":"初级 p141"}],"nq":4,"c":402},{"n":"C2","t":"阳宅一把扇，阴宅一条线","blocks":[{"t":"lead","v":"<b>阳宅后龙要打开如扇，阴宅落脉要清晰如线</b>——这是阳宅与阴宅点穴最直观的分别。"},{"t":"q","v":["在点穴阳宅和阴宅时有两点需要掌握：<b>1、阳宅一把扇；2、阴宅一条线。</b>如果是阳宅后龙要打开一把扇，如果是阴宅后龙落脉就要很清晰，是一条线。"],"src":"初级 p142"},{"t":"q","v":["<b>阳宅一把扇</b>：上图中村庄背后的龙脉层层开帐，一直到前面开了一个小帐，它不是一条细细的山脉过来，是很宽大的山脉象打开的一把纸扇一样。做阳宅时后面的靠山是要打开的。"],"src":"初级 p142"},{"t":"q","v":["<b>阴宅一条线</b>：做阴宅不能做这个位置，后面的靠山太宽了。"],"src":"初级 p143 图注"},{"t":"q","v":["阳宅往上走，有脉下来，狭窄处如果左右环抱有情，可以做阴宅。"],"src":"初级 p144"},{"t":"note","k":"key","v":"<b>同一座山上，宽处做阳宅、窄处做阴宅</b>——这条决定了同一块地能做什么。"},{"t":"note","k":"ref","v":"阳宅怎么把后龙\"打开\"（开面、花台）见 <b>B13</b>（家居 p122）与 <b>K 应用·家居城市</b>。"},{"t":"src","v":"初级 p142,143,144"}],"nq":4,"c":379},{"n":"C3","t":"点穴步骤：选好了还要反复论证","blocks":[{"t":"lead","v":"位置选好只是第一步，<b>穴位要靠反复论证与实物标定</b>。"},{"t":"q","v":["位置选好后，左右有环抱，水口关栏的很好，如果后面打开了一把扇，是不是可以建房子了呢？那还不行。<b>我们选好位置后要反复论证这个点。</b>"],"src":"初级 p144"},{"t":"p","v":"<b>现场怎么论证</b>——教材给了两个具体做法，都是拿竹竿当标尺："},{"t":"q","v":["昨天去四川南充，找好地后，因为四周的树太茂盛了，这个点在哪里还不是很清楚，找东家砍了一条最长的竹杆，上面挑了一块红色的布，<b>到对面的朝山上面看过来</b>，一看高了一点，重新回去选下面一点的位置，这样点穴有一定把握了。"],"src":"初级 p144"},{"t":"q","v":["那个地形前后左右都有一座山，师爷站在准备选的位置，让村里的年轻人<b>拿着四个大竹杆站在山顶上搞一个标志物立起来</b>，师爷通过前后左右四个点定位，就选了这个穴位，就是今天的莲忠堂。"],"src":"初级 p145"},{"t":"note","k":"key","v":"<b>平洋地最难定穴</b>，莲忠堂就是这种："},{"t":"q","v":["这个地四周是山，中间是田，六户人家一起来修这个房子，修一个大大的围屋。中间是平洋，四周是山，中间是田，在田的中间做房屋，定这个穴位很不好定，在中间做房屋，穴位定位很关键，<b>因为地形经过后天的改变，已经有些变化了。</b>"],"src":"初级 p144"},{"t":"p","v":"（莲忠堂是师爷 1949 年的成名作，在福建德化县；教材还记了它 1950 年建、1970 年代由 30 余人增至 100 多人、其中 30 多人吃公粮，以及师爷对 2005 年前后建房与风火二灾的应期判断。📎 应期类内容见 <b>M 断验与应事</b>。）"},{"t":"src","v":"初级 p144,145"}],"nq":4,"c":614},{"n":"C4","t":"证穴总纲：五法","blocks":[{"t":"lead","v":"<b>点穴里重点是证穴</b>，常用四五种，细论有十种；本套讲义详讲了五种。"},{"t":"q","v":["点穴里重点是证穴。<b>常用方法有四五种，仔细论有十种。</b>"],"src":"初级 p145"},{"t":"q","v":["证穴的方法有很多，用竹杆找地是其中一种。"],"src":"初级 p144"},{"t":"p","v":"初级第6课上依次讲了五种：<b>朝山证穴、明堂证穴、水势证穴、乐山证穴、鬼山证穴</b>（C5–C9）。其中前三种适用一般情况，后两种专为<b>横龙结穴</b>而设。"},{"t":"note","k":"warn","v":"教材说\"仔细论有十种\"，<b>本套讲义只展开了五种</b>，其余未见。若要补全需另找出处。"},{"t":"src","v":"初级 p144,145"}],"nq":2,"c":229},{"n":"C5","t":"朝山证穴","blocks":[{"t":"lead","v":"<b>高不过眉，低不过膝</b>；要的是朝我俯首的山，不是仰头骄傲的山。"},{"t":"q","v":["朝山证穴：站在穴位看前面的案山或朝山<b>高低适中（高不过眉，低不过膝）</b>，朝我有情，<b>对我俯首称臣、点头、恭敬的山形为贵。不是仰头、骄傲的山形。</b>"],"src":"初级 p145"},{"t":"p","v":"<b>案与朝的分别</b>："},{"t":"q","v":["站在房屋大门口看到正前面的山要么是朝山，要么是案山，<b>近“案”远“朝”</b>。"],"src":"初级 p146"},{"t":"q","v":["有些风水可能只能看到案山，堂局很小，朝山被案山挡住了看不到；有些风水案山很低，甚至看不到，只有朝山，堂局很开阔。"],"src":"初级 p146"},{"t":"note","k":"warn","v":"<b>两者至少要有一个</b>："},{"t":"q","v":["一个地，不一定案山和朝山都要有，但是<b>至少要有其中之一，要不然这个地可能就不行</b>。"],"src":"初级 p146"},{"t":"src","v":"初级 p145,146"}],"nq":4,"c":303},{"n":"C6","t":"明堂证穴","blocks":[{"t":"lead","v":"<b>水聚在谁跟前，穴就在谁那里</b>。"},{"t":"p","v":"先定义明堂——它比\"前面那块空地\"大得多："},{"t":"q","v":["明堂：站在大门口或碑前看到<b>左前方、正前方、右前方眼睛能看到的一切山水</b>。"],"src":"初级 p147"},{"t":"q","v":["朝山证穴也是明堂当中的一部分。左边青龙砂及青龙砂的水，前方朱雀砂及水，右边白虎砂及水都叫明堂。<b>朱雀砂就是朝山和案山。</b>"],"src":"初级 p147"},{"t":"p","v":"<b>怎么用它证穴</b>："},{"t":"q","v":["明堂证穴：<b>明堂不倾漏，水聚明堂</b>的意思。四方八方的水都能汇聚到明堂，再从一个地方流出去。有三四个地方来水，<b>聚水最多的位置就是我的房屋跟前</b>，叫明堂证穴。"],"src":"初级 p147"},{"t":"note","k":"key","v":"<b>这条能直接纠正点错的穴</b>："},{"t":"q","v":["如果水汇聚最多的地方不在跟前，在左边，<b>穴位可能在左边不在这里</b>。这一点要注意。"],"src":"初级 p147"},{"t":"note","k":"ref","v":"明堂的其余内容（形态、大小、锅底／棋盘）见 <b>E 峦头·水</b>。"},{"t":"src","v":"初级 p147"}],"nq":4,"c":358},{"n":"C7","t":"水势证穴","blocks":[{"t":"lead","v":"<b>有地没地全靠下臂</b>——看水口关不关得住。"},{"t":"q","v":["水势证穴：<b>有地没地全靠下臂。就是讲水口。</b>水汇聚之后，关栏的非常好。水有合聚有关栏，叫水势证穴。"],"src":"初级 p147"},{"t":"note","k":"warn","v":"<b>这是一票否决项</b>："},{"t":"q","v":["这三点是风水上最重要的。我们去看一个地，<b>水口不好，那就没地。</b>"],"src":"初级 p147"},{"t":"p","v":"教材给的例子说明了\"为什么十几条山脉里只选这一条\"："},{"t":"q","v":["那个地方很明显有水口砂三条大砂包裹过来，水口包裹的非常好。左右两边的山都环抱那个山头的。因为一条条下来有很多山脉，为什么有十几条山脉就选这一条呢？<b>因为所有的山都是汇聚到这一条山的，朝我有情的，护卫我的。</b>如果说山头都汇聚了，但<b>水口开阔，关栏不好，那这个地也不可选</b>。"],"src":"初级 p147"},{"t":"q","v":["水势证穴非常重要。<b>入山观水口，登穴看明堂。</b>"],"src":"初级 p147"},{"t":"note","k":"key","v":"「入山观水口，登穴看明堂」把 B2、C6、C7 串成了一条现场动线：进山先看水口定龙的走向，登上穴位再看明堂定穴的准头。"},{"t":"src","v":"初级 p147"}],"nq":4,"c":398},{"n":"C8","t":"乐山证穴（横龙结穴专用）","blocks":[{"t":"lead","v":"<b>见横龙结穴，必要枕乐，无乐则不真。</b>"},{"t":"p","v":"先说什么是横龙结穴："},{"t":"q","v":["乐山：点穴时，龙往前走，走到前面有环抱，可以结穴。但在行走过程时开帐可能也有一条脱脉下来，脱脉左右两边也有环抱，也可以结穴。但<b>龙是往前走的，在侧面来做地，叫横龙结穴</b>。"],"src":"初级 p148"},{"t":"q","v":["有很多马鞍形地、狗形地、绵犬形地都是横龙结穴地。"],"src":"初级 p148"},{"t":"p","v":"<b>乐山是什么</b>："},{"t":"q","v":["选好横龙结穴的这个位置，在山的后面也有一条山脉，起伏起伏，山脉也是往前走。<b>两山之间必有水</b>，即山脉后面有一条水，水过去还有一条山脉靠过来，叫乐山。"],"src":"初级 p148"},{"t":"q","v":["<b>只有横龙结穴才有。见横龙结穴，必要枕乐，无乐则不真。</b>"],"src":"初级 p148"},{"t":"p","v":"<b>乐山三种</b>："},{"t":"q","v":["<b>（1）特乐</b>：他山与我们点穴的这个山完全没有联系。是别的龙脉过来的，叫特乐。〔初级 p148〕","<b>（2）借乐</b>：自己的山脉开帐过来，分了两条小支，这条小支有个穴位，另一条小支就是它的乐山。实际就是借青龙砂出来的这条山脉。〔初级 p149〕","<b>（3）虚乐</b>：看起来有乐山实际上没有，山脉往前走，开帐，在这里点穴，正后方空，后面正中没有山过来，叫假乐山。"],"src":"初级 p149"},{"t":"note","k":"warn","v":"教材当场给了一个\"假地\"的现场判断："},{"t":"q","v":["昨天去四川南充点地，五年前东家自己点的地就是横龙结穴，但是背后就空，<b>背后既没有乐山也没有鬼山，是假地不能选。</b>"],"src":"初级 p149"},{"t":"src","v":"初级 p148,149"}],"nq":6,"c":564},{"n":"C9","t":"鬼山证穴：鬼尾比乐山更要紧","blocks":[{"t":"lead","v":"横龙结穴<b>必须有鬼尾</b>，没有鬼尾就是假地；<b>鬼尾在哪边，穴就点哪边</b>。"},{"t":"q","v":["山脉往前走，横龙结穴，山脉后面有条随龙水。同时山脉背后也有一条乐山，<b>这时还不一定有地</b>。横龙结穴除了有乐山之外，<b>还有比乐山更重要的一点背后要有鬼尾</b>。横龙往前走，横龙正后方有一个支撑点撑住，就是横龙背后也有一条脉脱下去，就是横龙的支撑点，叫鬼尾。象动物的尾巴一样。<b>在横龙结穴时，鬼尾是必须要有的。如果没有鬼尾就是假地。</b>"],"src":"初级 p149"},{"t":"note","k":"key","v":"<b>鬼尾直接定穴的左右</b>："},{"t":"q","v":["鬼尾也有很多种，<b>正后方有一条鬼尾支撑是最好的。点穴时鬼尾在哪个方位我们就选哪个方位。</b>如果鬼尾在正后方，点穴就选正中间。如果鬼尾偏左边，点的穴位也偏左边；如果鬼尾在右边，点穴就偏右边。"],"src":"初级 p150"},{"t":"note","k":"warn","v":"<b>两条鬼尾也算，别看漏了错过好地</b>："},{"t":"q","v":["还要注意一点，有时候正后方没有鬼尾，两边有两个鬼尾支撑，这个也算鬼尾，<b>也是孝顺鬼，为吉</b>。代表后代子孙对老祖宗很孝顺。"],"src":"初级 p150"},{"t":"q","v":["你去看地，一看没有鬼尾就不要了，<b>那你就可能错过好地了</b>，如果没有鬼尾，两边对称的位置有两个鬼尾脱下来支撑着这个山，然后前面横龙结穴，这也是可以的。……叫孝顺鬼尾。"],"src":"初级 p150"},{"t":"p","v":"教材在这里插了一句对风水先生的要求："},{"t":"q","v":["风水先生找地要俱备三样：<b>猪肚、铁脚、鹰眼。</b>鹰眼就是眼力要好，要会看地。"],"src":"初级 p150"},{"t":"src","v":"初级 p149,150"}],"nq":5,"c":584},{"n":"C10","t":"穴上九星：廖家九星与杨公九星","blocks":[{"t":"lead","v":"杨公九星是\"教科书式\"的单一星体，<b>廖家九星是走地理走出来的兼体</b>，更贴实战。"},{"t":"q","v":["<b>杨公九星</b>：天上的北斗七星加左辅、右弼星，贪狼、巨门、禄存、文曲、廉贞、武曲、破军、左辅、右弼。"],"src":"中级 p9"},{"t":"q","v":["<b>〔线下课20250618课堂补充〕</b> 杨公九星：贪狼（木）、巨门（土）、禄存（土）、文曲（水）、廉贞（火）、武曲（金）、破军（金）、左辅（金）、右弼（无）。"],"src":"中级 p9"},{"t":"p","v":"<b>两者的分别</b>："},{"t":"q","v":["廖家九星与杨公九星的区别在于：<b>杨公九星是教科书式的九星，完全按照星体的原则来单独分开的。而廖家九星更多的是从走地理的经验上来分的，更多的是几种星体的兼体。</b>"],"src":"中级 p9"},{"t":"q","v":["廖家九星是从实用的角度来分的，更侧重于实际应用。<b>比如金形就分了好几种，太阳金，太阴金。</b>"],"src":"中级 p9"},{"t":"p","v":"<b>廖家九星分龙上、穴上两套</b>："},{"t":"q","v":["<b>龙上九星</b>：贪狼、巨门、禄存、文曲、廉贞、武曲、破军、左辅、右弼。","<b>穴上九星</b>：太阳、太阴、金水、天财、紫气、天罡、孤曜、燥火、扫荡。"],"src":"中级 p9"},{"t":"p","v":"<b>穴上九星与杨公九星的对应</b>（线下课补充，这段是打通两套命名的钥匙）："},{"t":"q","v":["<b>〔线下课20250618课堂补充〕</b> 太阳、太阴即杨公九星里的武曲，金水就是武曲、文曲，天财即巨门，紫气即贪狼，天罡即破军，孤曜即禄存，燥火即廉贞，扫荡即文曲。"],"src":"中级 p9"},{"t":"h","v":"太阳"},{"t":"q","v":["<b>1、太阳：五行属金。</b>","头圆而身高者号太阳。","太阳一星即左辅，高圆覆钟金。","太阳星，以象言也。成象之至高至圆者，莫如日。凡有形上圆而身高者，假太阳以明之。圆者为金，故取用皆以金论，不可以为木论耳。有上下皆圆者，乃为正格。"],"src":"中级 p10"},{"t":"q","v":["<b>〔线下课20250618课堂补充〕</b> 太阳高大为阳，为男，应家里的男子或男主人，如“太阳金带笏头偏，内宫太监”。有太阳金这样的山形，同时有木星，笏头，上朝时拿的木牌，偏向一边，山形不端正，出的人也不端正，因为太阳金高大，有实权，为内宫太监，不是外宫太监，有实权的领导身边人，现代人是秘书。"],"src":"中级 p10"},{"t":"h","v":"太阴"},{"t":"q","v":["<b>2、太阴：</b>","五行土金","头圆而身带方者号太阴","太阴本是右弼传，形迹方更圆。","太阴者，以象言也，造化之理。阳得其全，阴得其半，故太阴多缺。凡有形上圆带方而身低者，假太阴以名之。圆为金，方为土，故取用皆以金土论。而金之性为多，以金受土生也，不可以为水而论之。唯体端正无缺者，乃为正格。"],"src":"中级 p10,p11"},{"t":"q","v":["注：五行土金。不象金星，太低了。头圆而身带方者号太阴。下面是土形，上面有一点点金星体。又象土又象金。<b>实为土金的兼体。</b>"],"src":"中级 p10,p11"},{"t":"q","v":["<b>〔线下课20250618课堂补充〕</b> 太阴金，低矮的金星，……<b>太阴金主女。</b>“太阴金穴后，丈人宰相”，“峨眉金居左畔，女婿为官”。峨眉金也属于太阴金一类。太阴金与女的有关，要么是娶的夫人很厉害，要不就是嫁出去的女儿有能力。"],"src":"中级 p11"},{"t":"h","v":"金水"},{"t":"q","v":["<b>3、金水：</b>","五行金水","头圆而身曲者号金水","金水原来名武曲，三脑如金宿。","金水者，以质言也。金熔则圆，水流则曲。凡有形上圆而曲者，正以金水名之，故取用皆以金水论。而水性为多以受金生故也。<b>唯要圆曲分明，乃为正格。</b>"],"src":"中级 p11,p12"},{"t":"q","v":["注：头圆而身曲者号金水。金水也叫金星三台，有三个圆的金水体。因为有三个金连在一起，又是文曲，又是三台。<b>这种地形就很贵。</b>"],"src":"中级 p12"},{"t":"note","k":"warn","v":"<b>穴上九星其余六星</b>（天财、紫气、天罡、孤曜、燥火、扫荡）中级 p9–p20 尚有大段原文，本稿只写到金水。<b>这是本类最大的缺口</b>，需另起一轮。"},{"t":"src","v":"中级 p9,10,11,12"}],"nq":13,"c":1428},{"n":"C11","t":"二十四凶穴与五星结穴（未展开）","blocks":[{"t":"note","k":"warn","v":"<b>本稿尚未整合的两大块</b>，都在中级："},{"t":"ul","v":["<b>五星结穴</b>（中级 p9–p35，视频1-2）：木星结穴（倒地木、照天蜡烛、将军大坐、仙人大坐形、直木）、火星结穴、土星结穴（土腹藏金／土腹流金、土角挂金）、金星结穴（金星开窝）等，条目清单已在 `01-知识体系骨架.md` 的 C 类里。","<b>论二十四凶穴</b>（中级 p36–p57，视频3-4）：31 个条目。","<b>论地</b>（中级 p101–p138，视频7）：152 个条目，是中级篇幅最大的一节，多为现场案例。"]},{"t":"p","v":"这三块合计约占 C 类知识点的六成。<b>没有匆忙下笔，是因为它们几乎全是形名与案例，必须逐条对着原文写，凭印象归纳一定出错。</b>"},{"t":"src","v":"中级 p9-138（待整合）"}],"nq":0,"c":322},{"n":"","t":"本类进度","blocks":[{"t":"p","v":"C 类共 152 个知识点。本稿 11 条覆盖了<b>点穴证穴的完整方法论</b>（穴的定义、阳宅阴宅之别、点穴步骤、证穴五法）与<b>穴上九星的前三星</b>，约占三成。"},{"t":"p","v":"未展开：五星结穴、二十四凶穴、论地案例、穴上九星后六星。"}],"nq":0,"c":114}]},{"c":"D","name":"峦头·砂","intro":"跨教材整合稿，体例同 A–C。**只用教材原文**，引文照录（含原稿用字与错字，不代改）。 出处：`初级`｜`中级`｜`家居`＝家居风水高级课程｜`高级`｜`第一课`。","items":[{"n":"D1","t":"砂是什么","blocks":[{"t":"lead","v":"穴位<b>前后左右的山</b>都叫砂——除了那条走过来的龙。"},{"t":"q","v":["察砂：看风水找地的过程当中，要来考虑这个穴位，也是房屋修建的这个地方，前后左右的这个山形，叫察砂。"],"src":"家居 p167"},{"t":"note","k":"warn","v":"<b>龙与砂的分界</b>："},{"t":"q","v":["来龙的最近端，起伏变化绵延不断的叫龙，<b>不是把所有绵延不断的山脉都叫砂，不对</b>。龙脉一直往前走，走到龙水交汇到房屋正后方的靠山，象椅子背，叫玄武砂。<b>也叫穴星山</b>。"],"src":"初级 p98"},{"t":"p","v":"<b>\"砂\"这个字的来历</b>，是从教学工具来的："},{"t":"q","v":["砂同\"沙\"，沙盘，是古人学风水的一种方法。三僚的廉泉书院是教学风水的书院，福建和广东有很多风水爱好者来三僚学习，在学习过程中就是<b>用沙子或大米来堆沙盘</b>教学怎么找地做地。"],"src":"家居 p167"},{"t":"note","k":"warn","v":"<b>书院名两本不一致，未擅改</b>：家居作「<b>廉</b>泉书院」〔家居 p167〕，《第一课》第 7 课作「<b>莲</b>泉书院」（廖文政所修，从明朝用到太平天国被战火所烧）。两处指的应是同一所，用字待考。"},{"t":"p","v":"<b>现场站位</b>（城市里最实用的一条）："},{"t":"q","v":["假如说我们要准备购买这个房屋，那么我们一般就<b>站在阳台上</b>。如果说你购买的是别墅，那就站在大门口来看，如果说你购买了房子，它没有阳台，它就是一个窗户，那还是<b>站在窗户边</b>来看房子外面四周前后左右的山形，这个叫察砂。"],"src":"家居 p167"},{"t":"src","v":"初级 p98｜家居 p167"}],"nq":4,"c":563},{"n":"D2","t":"四象：借的是天上的名，用的是身上的方向","blocks":[{"t":"lead","v":"<b>左青龙、右白虎、前朱雀、后玄武</b>——按穴位的前后左右论，<b>不按东南西北</b>。"},{"t":"q","v":["风水上是以穴位前后左右来论\"左青龙、右白虎、前朱雀、后玄武\"。<b>不是按照东南西北来论，不是根据天象论。</b>"],"src":"初级 p98"},{"t":"p","v":"家居讲了这套名字的来历，也讲清了它跟天文原本的分别："},{"t":"q","v":["\"青龙、白虎、朱雀、玄武\"，在风水上叫四象。四象的概念，源自于天空当中的28星宿……古人把天上这些星根据它的形状就分成了28组，这叫28星宿。又根据东南西北，又分成了4组。"],"src":"家居 p168"},{"t":"q","v":["东边7主星，称为青龙。右边7主星称为白虎。南边有七主星，称为朱雀。北边有七主星称为玄武。……玄武就是龟形，青龙就是龙形，白虎就是虎形，朱雀就是鸟形。"],"src":"家居 p169"},{"t":"note","k":"key","v":"<b>关键的一句</b>："},{"t":"q","v":["我们古人讲的是28星宿，是<b>东青龙、西白虎、南朱雀、北玄武</b>。但是我们在风水上就变成了<b>左青龙、右白虎、前朱雀、后玄武</b>，这是我们在风水上<b>借用</b>了四象的概念。"],"src":"家居 p169"},{"t":"p","v":"<b>玄武就是靠山</b>："},{"t":"q","v":["察砂时，就是要观察这四象。左边青龙砂，正前方的朱雀砂，右边的白虎砂。房屋后面的玄武砂。<b>玄武砂实际上就是我们的穴星山，就是我们房屋的靠山。</b>"],"src":"家居 p169"},{"t":"q","v":["上一讲讲来龙的时候，就是入首龙，跟入首龙相连的最后这座山就是我们的穴星山，就是玄武砂，就是靠山。"],"src":"家居 p169"},{"t":"note","k":"ref","v":"《第一课》第 24 课以通俗版讲同一件事，可对照。"},{"t":"src","v":"初级 p98｜家居 p168,169"}],"nq":6,"c":579},{"n":"D3","t":"砂的作用：藏风得水，但两头都不能过","blocks":[{"t":"lead","v":"没有砂是<b>空旷无收</b>，砂太高是<b>四山高压人丁稀</b>。"},{"t":"q","v":["房屋四周的砂的作用：<b>藏风得水</b>。如果房屋四周没有砂，就是空旷无收，风直来直去，没有护卫，孤零零的，不收堂气，不藏风聚气，就不是好风水。"],"src":"初级 p98"},{"t":"q","v":["假如房屋四周的砂特别高，四山高压，外面的风进不来，里面的风出不去，<b>四山高压人丁稀</b>。"],"src":"初级 p98"},{"t":"note","k":"key","v":"这两句正是 <b>A2 藏风</b>那条原理在砂上的落地：要环抱，但要的是动态平衡。"},{"t":"src","v":"初级 p98"}],"nq":2,"c":204},{"n":"D4","t":"明堂三层：内、中、外，各管几代","blocks":[{"t":"lead","v":"<b>内明堂管当代，也是唯一能裁剪的那一层。</b>"},{"t":"q","v":["明堂：站到大门口、阳台上能看到的左边、前方和右边的山形和水，这叫明堂。"],"src":"家居 p170"},{"t":"q","v":["明堂又分<b>内明堂、中明堂、外明堂</b>。小的地，就直接分内明堂和外明堂。……这个停车场就是我们内明堂，我们看到的这条公路和这个案山，就是中明堂，远处的朝山，这些山峰就属于外明堂。"],"src":"家居 p170"},{"t":"note","k":"key","v":"<b>为什么要先把内堂做好</b>："},{"t":"q","v":["一般说来我们自己建房屋或买房屋，应该首先注重内明堂，为什么？<b>是因为内明堂管当代，管现在。</b>我们古人很多不是很注重，只要后代子孙好就行了。我们今天的人很都很讲究实际，一定当代要做好，那就是把内堂要做好。<b>一般做内堂，都是我们自己可以裁剪的。</b>"],"src":"家居 p170"},{"t":"q","v":["其实我们讲风水上的裁剪功夫主要就是我们讲的<b>内堂裁剪</b>。一般中明堂外明堂裁剪不了，那座大山移不走，那个大房子你也改不了。<b>我们能改的就是内堂。</b>"],"src":"家居 p170"},{"t":"q","v":["所以说我们在做阴宅的时候讲的叫\"<b>九尺内堂</b>\"做法，一般阴宅内堂做三米。做三米符合单步。"],"src":"家居 p170"},{"t":"p","v":"<b>三层各管几代</b>："},{"t":"q","v":["中明堂可能实际上就要管到第二代到第三代、第四代。外明堂可能管三四代，四五代，五六代以外。"],"src":"家居 p170"},{"t":"note","k":"warn","v":"<b>代数不是死数</b>："},{"t":"q","v":["这个到底是管多少代，<b>还根据这个堂局大小来定</b>，那大的有些可以管几十代，我们讲三元不败可以管几十代。那小的明堂，可能就是几代两三代。那到底多远算一代？<b>十步算一代，一步有多远，没有具体的数字。只是大概估计就行了。</b>"],"src":"家居 p170,171"},{"t":"note","k":"ref","v":"明堂证穴见 <b>C6</b>；明堂的水见 <b>E 峦头·水</b>。"},{"t":"src","v":"家居 p170"}],"nq":7,"c":665},{"n":"D5","t":"有情与无情：一句话的判准","blocks":[{"t":"lead","v":"<b>起好作用就是有情，起坏作用就是无情。</b>"},{"t":"q","v":["有情就是我们看到的这个山峰，它是端庄秀丽的，它是来护卫我们的，他不是来加害我们的。这个叫有情。"],"src":"家居 p171"},{"t":"q","v":["无情是看到这个山峰，对我是逼压的，或者这个水对我是冲射的，对我是当堂直泻的，对我是斜飞的，这个就是无情。"],"src":"家居 p171"},{"t":"q","v":["<b>总之一句话，这个山水只要是起好作用。就叫有情，山水只要是起坏作用，就是叫无情。</b>"],"src":"家居 p171"},{"t":"src","v":"家居 p171"}],"nq":3,"c":177},{"n":"D6","t":"察砂五点","blocks":[{"t":"lead","v":"<b>秀丽粗恶、端正歪斜、高低逼压、环抱反背、顺砂逆砂</b>——初级讲的五条，按顺序看。"},{"t":"p","v":"先记一句次第上的话："},{"t":"q","v":["<b>一流地师观星斗，二流地师观水口，三流地师端着罗盘满山走</b>，是经验的次递过程。观星斗的先生也要看水口，也要拿着罗盘满山走的。<b>学风水的过程是三流到二流到一流，不可能一开始就是一流先生的。</b>"],"src":"初级 p99"},{"t":"h","v":"一、秀丽与粗恶"},{"t":"q","v":["察砂的第一点：看砂的秀丽与粗恶。<b>相山如同相人。有什么样的山出什么样的人。</b>老百姓说：一方水土养一方人。"],"src":"初级 p99"},{"t":"p","v":"这一条背后是<b>类象</b>——教材专门解释了这个思维方式："},{"t":"q","v":["类象：是老祖宗通过取象比类，把很多看似没有关联的事物，有一些特殊的征象的事物归为同一类，用八卦代表万事万物。<b>正因为有类象才有易经的诸多预测。</b>"],"src":"初级 p99"},{"t":"q","v":["例如：中医很多中药的用法，都体现出类象的概念。如水蛭吸血很厉害……人体内有淤血时把水蛭晒干磨粉冲水喝能活血化淤……如麻黄长的象关节，能治关节炎。……脑中风大脑不好使，给他吃点猪脑髓，<b>以脑补脑，以脏补脏</b>。"],"src":"初级 p100"},{"t":"q","v":["风水上更是这样，<b>山清秀生的人也清秀，山粗恶生的人也粗恶</b>。如江浙一带苏杭的女子生的小巧，苏杭一带的山不高大。北方的同学都很魁梧，北方的太行山都很高大。四川的山，峨眉天下秀，四川出美女不奇怪。"],"src":"初级 p100"},{"t":"note","k":"warn","v":"<b>粗恶在哪个位置，轻重不同</b>："},{"t":"q","v":["如果粗恶的山在穴位前面在阳宅前面，是<b>案山不好，朝山远还好一点</b>。需要制化避免。"],"src":"初级 p100"},{"t":"h","v":"二、端正与歪斜"},{"t":"q","v":["察砂第二点：看山的端正与歪斜。如果<b>山峰端正人就端正</b>。……上面山尖是歪斜生的人就是歪斜。"],"src":"初级 p100"},{"t":"q","v":["<b>山峰端正一定出正能量正思维的人。山峰歪斜一定出想走捷径和走旁门左道的人。</b>"],"src":"初级 p102"},{"t":"p","v":"教材给了一个断法上的实用建议："},{"t":"q","v":["你会看风水了，你有一个合作伙伴，你到他家祖地去一看，你就知道这个人值不值得你交往。从风水上看，一眼便知。"],"src":"初级 p102"},{"t":"note","k":"warn","v":"<b>同一种山形不能套死</b>，教材当场提醒："},{"t":"q","v":["只有多看多实践，你才知道什么样的地出什么样的人出多大的官，才不会说错。<b>如果说某个地能出上将，你说哪里去看哪个山峰出上将，就犯了教条主义。一定要经验积累非常重要。</b>"],"src":"初级 p101"},{"t":"h","v":"三、高低与逼压"},{"t":"q","v":["察砂第三点：山的高低与逼压。<b>四周的山高为逼压。</b>"],"src":"初级 p102"},{"t":"q","v":["如果发现四周有山逼压，居家风水是<b>人丁稀</b>，后代子孙不多。做生意<b>客源不多</b>。"],"src":"初级 p103"},{"t":"p","v":"<b>化解与一个失败案例</b>："},{"t":"q","v":["正前方的楼太高了，虽然隔了一条路，这个高楼逼压。老板问怎么办？王老师说<b>在前面开个水池比较好</b>。"],"src":"初级 p102"},{"t":"q","v":["没想到老板把水池开在酒店正厅里面。开业时1000多一晚，现在是500多一晚。<b>水池化解逼压，要开在酒店外面停车的地方。</b>"],"src":"初级 p103"},{"t":"note","k":"warn","v":"<b>青龙高不等于坏</b>——朱德出生地那个例子，教材讲得很辩证："},{"t":"q","v":["问：青龙方比主屋高很多，会有什么象征？答：<b>青龙方高，只要环抱有情没有问题。</b>这个楼修的高有点奴婢欺主。"],"src":"初级 p103"},{"t":"q","v":["这只是很小的一点，还不能说是奴婢欺主的核心。……<b>不能说以后一看到这样房子就一定有奴婢欺主的嫌疑。一定要辩证看待。</b>这个高房子只是内砂，隔的很近，但是<b>近、中、远都要去看</b>。不能只看这一点。"],"src":"初级 p103"},{"t":"note","k":"key","v":"由此教材点出<b>看风水的两个核心</b>："},{"t":"q","v":["看风水有两个核心：<b>1、整体观。2、类象概念。</b>没有整体观，只看其中某个细节，被眼前不重要的细节所蒙蔽，不能抓住主要矛盾就断不准风水，做不好风水。"],"src":"初级 p103"},{"t":"p","v":"同一条也解释了师爷自家老房子为什么\"白虎压青龙\"却没问题："},{"t":"q","v":["师爷的老房子为七字屋，青龙方没有厢房，白虎方修了厢房，有人会认为青龙空，白虎压青龙，白虎高青龙低。从整体观来看，<b>青龙方就是要开阔，来水宽大，白虎方就是要水口紧锁。那个地才能达到藏风得水的目的。</b>"],"src":"初级 p103"},{"t":"h","v":"四、环抱与反背"},{"t":"q","v":["察砂第四点：砂的环抱与反背。<b>环抱为有情</b>，对我起好作用。<b>反背叫无情</b>，对我起坏作用。"],"src":"初级 p104"},{"t":"q","v":["<b>砂手反背，出忤逆无情之子。</b>凡是有不孝敬父母的风水就有这样的象征。通过家庭的发展状况也能推出大致的风水状况。"],"src":"初级 p104"},{"t":"q","v":["图中的白虎砂是砂手反背，<b>胳膊往外拐</b>。家里出忤逆无情之辈。假如有三个后代，<b>三房</b>出忤逆无情之辈。"],"src":"初级 p104"},{"t":"h","v":"五、顺砂与逆砂"},{"t":"q","v":["察砂第五点：顺砂与逆砂。水往前走，砂也往前走，为顺水砂。\"<b>左砂顺水长子去，右砂顺水三子离</b>\"。"],"src":"初级 p105,106"},{"t":"src","v":"初级 p99,100,101,102,103,104,105"}],"nq":22,"c":1803},{"n":"D7","t":"水口砂：有地没地全看下臂","blocks":[{"t":"lead","v":"<b>水口关不关得住，直接决定这块地成不成。</b>"},{"t":"q","v":["除了四周的山叫砂之外，在一些特定的地方也叫砂，如房屋四周出水口的方向有山把水挡住了，叫<b>水口砂</b>。水口砂起到了一个水口有关栏的作用。"],"src":"初级 p98"},{"t":"q","v":["肉眼看到水被关栏住了，能够让水滴水不漏，水口关栏的好，叫藏风得水的好，<b>有财</b>。如果水口关栏的不好，<b>没有财</b>。"],"src":"初级 p98"},{"t":"q","v":["水口特别重要，<b>入山观水口，登穴看明堂</b>。或者说\"<b>有地没地全看下臂</b>\"。水口砂关的好，肉眼看到水出不去，好风水。"],"src":"初级 p98"},{"t":"p","v":"<b>一个皇帝级的案例</b>——朱棣为什么迁都："},{"t":"q","v":["朱棣问廖均卿：南京的风水好不好？廖均卿答：好是好，只是<b>出水口朝外</b>。朱棣说：朕意嫌之。出水口朝外是水口关栏的不好，没风水。<b>所以朱棣迁都北京。</b>"],"src":"初级 p98"},{"t":"q","v":["水口关栏的不好，廖均卿为什么还要说一句好呢？是指南京这个地方还可以，不能说太差，<b>一个谦虚之词</b>。"],"src":"初级 p98"},{"t":"p","v":"<b>水口砂按形状分四种</b>："},{"t":"q","v":["水口砂还可以细分：1、左右两边的山很高大，可以说成<b>狮象把水口</b>；2、如果左右两边的山比较矮，可以说成<b>龟蛇把水口</b>；3、如果左右两边的山立起来，象华表一样，叫<b>华表</b>；4、如果象士兵一样站在水口叫<b>捍门</b>。等等。"],"src":"初级 p98"},{"t":"note","k":"key","v":"<b>高山与平原用不同的说法</b>："},{"t":"q","v":["<b>高山是四象把水口，平原平地是龟蛇把水口。</b>"],"src":"初级 p427"},{"t":"note","k":"ref","v":"水口本身（观水口、出水）见 <b>E 峦头·水</b>；水势证穴见 <b>C7</b>。"},{"t":"src","v":"初级 p98,427"}],"nq":7,"c":636},{"n":"D8","t":"官鬼禽曜砂","blocks":[{"t":"lead","v":"四句口诀各管一处——<b>官在朝山背后，鬼在穴山背后，禽在水中心，曜在龙虎肘后。</b>"},{"t":"q","v":["问君何者谓之官，朝山背后逆拖山。","问君何者谓之鬼，穴山背后撑者是。","问君何者谓之禽，龟鱼生在水中心。","问君何者谓之曜，龙虎肘后石尖生。"],"src":"初级 p426"},{"t":"p","v":"<b>逐条落地</b>："},{"t":"q","v":["朝山背后拖了一条山脉下来，照片里看不到。"],"src":"初级 p426"},{"t":"q","v":["横龙结穴后面的鬼尾，鬼尾有好几种。<b>横龙结穴背后一定要拖个尾巴。</b>"],"src":"初级 p427"},{"t":"q","v":["<b>禽砂：水口砂。</b>龟鱼守水口，龟鱼为禽曜砂。在水口方，比较低矮的象龟形、鱼形、蛇形一样的山形，称为禽砂。"],"src":"初级 p427"},{"t":"q","v":["<b>曜砂：龙虎两边生的尖砂，为曜砂。曜砂为贵。</b>"],"src":"初级 p427"},{"t":"q","v":["水口砂的龟鱼砂称为禽砂，龙虎两边的砂称为曜砂。"],"src":"初级 p428"},{"t":"p","v":"<b>实例</b>："},{"t":"q","v":["此为山西运城闻喜县裴氏宰相村，左右龙虎之外都有曜砂，层层环抱，堂局水聚明堂。这个地形比较好。"],"src":"初级 p428"},{"t":"note","k":"ref","v":"鬼尾（鬼砂）在点穴中的用法见 <b>C9 鬼山证穴</b>。"},{"t":"src","v":"初级 p426,427,428"}],"nq":7,"c":387},{"n":"D9","t":"应砂与乐砂","blocks":[{"t":"lead","v":"<b>应砂在案山背后，乐砂在穴星山背后</b>；乐砂只有横龙结穴才讲。"},{"t":"q","v":["<b>应砂</b>：就是在案山后面拖的砂。"],"src":"初级 p428"},{"t":"q","v":["<b>乐砂</b>：穴星山后面除了鬼尾外，后面还有山支撑着，这个山就叫乐砂，又叫乐山。……<b>横龙结穴就有乐砂。</b>"],"src":"初级 p428,429"},{"t":"note","k":"warn","v":"<b>分不清就不必强分</b>："},{"t":"q","v":["案山和应砂分辨不出来，<b>统称为案山也没有问题</b>。"],"src":"初级 p429"},{"t":"p","v":"<b>横龙结穴的两个条件</b>（与 C8／C9 是同一件事的两种说法）："},{"t":"q","v":["横龙结穴的条件：<b>1、鬼尾；2、乐山。</b>有的鬼尾是一个，有的是两个。有的鬼尾在左边，有的鬼尾在右边。不同的情况根据不同的地形来。"],"src":"初级 p429"},{"t":"src","v":"初级 p428,429"}],"nq":4,"c":279},{"n":"D10","t":"星体砂与富贵贫贱砂","blocks":[{"t":"lead","v":"<b>砂也讲五星九星</b>；再按肥圆／秀尖／斜臃肿分富、贵、贱。"},{"t":"q","v":["星体砂就是我们前面讲的五星，九星。砂也讲五星、九星。<b>木星、火星主贵，土星、金星主富。</b>"],"src":"初级 p429"},{"t":"q","v":["九星里有九九八十一星。"],"src":"初级 p430"},{"t":"p","v":"<b>富贵贱三分</b>："},{"t":"q","v":["砂有三：富贵贱。<b>肥圆正为富局，秀丽尖为贵局，斜臃肿为贱砂。</b>"],"src":"初级 p430"},{"t":"q","v":["四周山形高大、饱满就是富砂。<b>金星、土星为富砂。</b>一般高大饱满肯定是金星土星。"],"src":"初级 p430"},{"t":"q","v":["<b>尖奇山峰主贵。</b>"],"src":"初级 p431"},{"t":"p","v":"<b>案例</b>（同一个人，故居与出生地两块地判然不同）："},{"t":"q","v":["此地是清朝末期富豪张弼世故居和他的出生地。<b>老师说故居这个地出不了富豪</b>，后来打听到右前方的房子是他出生地，高山落脉下来，大江水环抱，周围山形非常圆满，一个个都是富砂，<b>这种就是出大富之人</b>。"],"src":"初级 p431"},{"t":"q","v":["（张弼世故居在其他课程讲过，为<b>退财地</b>。他的出生地出富豪）"],"src":"初级 p431"},{"t":"note","k":"key","v":"<b>看砂要先给东家一个初判，再上理气</b>："},{"t":"q","v":["哪些山发富，哪些山是发贵，哪些山不发人，到任何一个地方去看风水或做风水要观察清楚后告诉东家，看这个地方是出读书人是发财，<b>先有初步判断，然后再从理气上来断，两者要结合起来</b>。"],"src":"初级 p431"},{"t":"note","k":"ref","v":"五星九星的辨形见 <b>B10–B12</b>。"},{"t":"src","v":"初级 p429,430,431"}],"nq":8,"c":526},{"n":"D11","t":"中正邪淫砂与探头砂","blocks":[{"t":"lead","v":"<b>砂如圆净，定产忠贞；势或欹斜，必生淫佞。</b>"},{"t":"q","v":["砂如圆净，定产忠贞。势或欹斜，必生淫佞。"],"src":"初级 p432 图注"},{"t":"q","v":["山峰端正，出的人端正，这种家庭出不了叛徒。"],"src":"初级 p432 图注"},{"t":"q","v":["山峰歪斜，出的人狡猾淫乱之辈。《指迷赋》里还会讲到仙裙山等，都是指山峰歪斜之象，出淫乱之辈。"],"src":"初级 p433"},{"t":"p","v":"<b>探头砂</b>——三本都提到，是最常见的一种凶砂："},{"t":"q","v":["<b>前山露顶，男女奸偷</b>：前山露顶即探头砂。就是前山在这里，后面的山露出一个脑袋出来。<b>在乡下的风水当中经常容易看到。</b>"],"src":"初级 p247"},{"t":"q","v":["<b>砂如探头、作贱阴谋</b>：探头砂，偷盗、淫乱、小聪明。"],"src":"中级 p70"},{"t":"src","v":"初级 p247,432,433｜中级 p70"}],"nq":5,"c":264},{"n":"D12","t":"城市察砂：从\"好不好看\"入手","blocks":[{"t":"lead","v":"城市第一标准是<b>四砂秀丽，不要粗恶破败</b>；而内堂杂乱<b>影响到什么程度、什么部位</b>都有讲究。"},{"t":"q","v":["城市风水察砂的第一个标准：<b>要四砂秀丽，不要粗恶破败。</b>四砂就是我们讲的青龙、白虎、朱雀、玄武。"],"src":"家居 p171,172"},{"t":"q","v":["粗恶破败就是看起来不好看。……此房子整个地形来说，堂局不正，有几栋破败的楼，叫粗恶破败。"],"src":"家居 p172"},{"t":"p","v":"<b>在建的工地也算粗恶</b>，但可以减轻："},{"t":"q","v":["我们看到正在施工的还有塔吊的正在施工的这些楼，我们可以把它看做粗恶，<b>当然现在很多施工时他围起来，那这种情况就减轻了很多</b>。"],"src":"家居 p173"},{"t":"h","v":"内堂杂乱影响什么"},{"t":"note","k":"key","v":"这是本条最实用的一段，教材把<b>轻重</b>和<b>部位</b>分开讲："},{"t":"q","v":["<b>1、影响的轻重程度。</b>近处内堂跟前这一片房顶，内堂杂乱不秀丽，粗恶破坏，也叫内堂杂乱。对我们的影响主要是<b>影响人的情志</b>。时间久了，<b>影响人的相貌</b>。那再严重……那可能就会<b>影响人的身体</b>。如果你长期居住，就是影响相貌情志。如果说更严重，那就是影响健康。"],"src":"家居 p174"},{"t":"q","v":["<b>2、影响的部位</b>：一般来说在内堂中央出现的这些破败，根据我们以前学过的八卦风水，就属于是<b>影响脾胃</b>。假如说是破败在我们的<b>乾卦方，会影响头部</b>。如破败的方位在<b>艮方，它会影响我们的脚</b>。<b>是通过八卦方位来推算。</b>"],"src":"家居 p174"},{"t":"q","v":["大家要知道，风水对人影响的主次。这个地形，我们还是可以选。"],"src":"家居 p174"},{"t":"h","v":"小东西要不要管"},{"t":"note","k":"warn","v":"<b>判断标准是\"大小 + 落在什么方位\"</b>，不是见煞就化："},{"t":"q","v":["首先在我们房子右前方有这个电线杆，有这个电线缠绕，破败不秀丽，这个一定要测量。这个破败不秀丽如果说是在凶方，<b>在八煞劫煞方不好</b>，找点关系，想点办法把它移除。<b>但是如果没在八煞劫煞方，那也无所谓，不要去管它，因为它小</b>……"],"src":"家居 p175"},{"t":"q","v":["这种不秀丽，如果在劫煞方，那我们真的要注意。<b>最怕劫煞方，其次才是八煞方。</b>"],"src":"家居 p175"},{"t":"q","v":["问：这个楼顶上的水塔，会不会有影响？答：高的这个水塔也还比较秀丽，也不逼压，所以说这个水塔对他没有什么影响。阳台上拉的这个晒衣架，这个影响小，因为太小了嘛。"],"src":"家居 p175"},{"t":"note","k":"ref","v":"八煞、劫煞的推算见 <b>H 理气·水法砂法</b>。"},{"t":"src","v":"家居 p171,172,173,174,175"}],"nq":9,"c":929},{"n":"D13","t":"消砂纳水：看砂之后要动手","blocks":[{"t":"lead","v":"<b>看风水时叫察砂观水，做风水时叫消砂纳水。</b>"},{"t":"q","v":["看风水时叫<b>察砂观水</b>，做风水时叫<b>消砂纳水</b>。"],"src":"初级 p433"},{"t":"q","v":["消砂纳水是我们在观察地形做风水时<b>如果砂为凶要想办法把它消除</b>，不管是从峦头上用<b>堆土、开水池、栽树</b>，或者从理气上用<b>立向分金</b>等等，把不好的因素消除掉，叫消砂。"],"src":"初级 p433"},{"t":"q","v":["好的砂用罗盘通过立向、开水池等<b>收进来</b>，好的砂让他更好。如尖峰能发贵，在理气上一做，让他发个大贵。好砂纳进来为我所用叫纳砂。"],"src":"初级 p433"},{"t":"q","v":["消砂纳水可以叫<b>消砂纳砂消水纳水</b>。不好的要消除，好的要纳。"],"src":"初级 p434"},{"t":"note","k":"warn","v":"<b>砂与水的应验速度不同</b>："},{"t":"q","v":["<b>砂水速缓：水应的祸福速，砂迟。</b>当然也有特殊情况，比如断反弓，不是一去就断反弓，如中山市看到反弓，<b>有财但财不是你的</b>。那个老板说正确。"],"src":"初级 p434"},{"t":"src","v":"初级 p433,434"}],"nq":5,"c":369},{"n":"D14","t":"看砂的动线：先看后龙，再看堂局，最后回头看穴星","blocks":[{"t":"lead","v":"教材给的顺序是<b>先上后山，再站穴看堂，最后走到对面回望</b>。"},{"t":"q","v":["王老师看风水的经验：<b>1、一般不先看堂局，先看房屋后面的来龙，后面的靠山，甚至有必要登到后面山顶去看一看</b>；2、站在大门口、站在穴星山、站在穴位、站在碑前看整个堂局、整个砂手、看看水口；3、<b>到整个明堂正前方对面看整个穴星山</b>。"],"src":"初级 p106"},{"t":"note","k":"key","v":"这条与 <b>A7 整体观</b>、<b>B12「富贵龙身出，看地时后面靠山最重要」</b>是同一个意思的三种说法：<b>不先看眼前的堂局。</b>"},{"t":"p","v":"<b>下断语之前也是同一条</b>："},{"t":"q","v":["下断语前要<b>龙穴砂水向、前后左右结合来看</b>。"],"src":"初级 p106"},{"t":"src","v":"初级 p106"}],"nq":2,"c":284},{"n":"","t":"本类未收入精讲的条目","blocks":[{"t":"p","v":"D 类共 68 个知识点，上面 14 条覆盖主干。以下暂未展开："},{"t":"ul","v":["<b>吉凶砂五十七图</b>（中级 p58–p70，视频5）：只有 3 个条目名，但正文是逐图讲解，属图文强绑定内容，<b>没有图很难整合</b>，需读图或另找出处。","<b>形煞细目</b>：天斩煞、尖角直射、孤峰、反背等在家居第 10 课与 K 类（化解）里成体系出现，按体例归 <b>K 应用·家居城市</b>，那边写。","<b>地漏与窝煞的区别</b>：条目在初级线下课笔记里，原文简略，未找到完整讲解。","<b>现代形煞</b>（风力发电、电线塔、信号塔）：散见于家居各课的问答，已在 D12 收了电线杆与水塔两例，其余待整理。"]}],"nq":0,"c":295}]}];
